    ["peoples"] = "Humanoïdes",
    ["undead"] = "Les morts-vivants",
  },
  families = {
    ["air-elementals"] = { title = "Élémentaires d'air", note = { { "Des diables de poussière traversent les champs ouverts, tandis que de plus grands tourbillons prennent forme en Désolace et en Silithus. Un élémentaire d'air se voit le mieux à ce qu'il rassemble autour de lui : poussière, nuage, et les objets mal attachés qu'un voyageur croyait solidement rangés." }, { "Le Marteau du crépuscule invoque des puissances élémentaires dans le désert du sud. Une tempête rencontrée là-bas peut avoir autre chose derrière elle qu'un temps agité. Le vent a pris forme, et quelqu'un l'a peut-être invité." } } },
    ["bandits-and-mercenaries"] = { title = "Bandits et mercenaires", note = { { "Un avis de recherche donne d'un hors-la-loi l'image d'un problème solitaire. Les camps des Bat-le-désert à Tanaris et le camp retranché de Kurzen à Strangleronce suggèrent le contraire : des gardes, des provisions et une organisation qui survit à la perte de n'importe quel bandit." }, { "Les hommes de Kurzen étaient des soldats avant que la jungle ne s'empare de leur expédition. D'autres travaillent pour une solde ou guettent les routes. Leurs raisons diffèrent, et les bannières peuvent manquer, mais un camp gardé a beaucoup en commun avec l'armée à laquelle il a appartenu." } } },
    ["basilisks"] = { title = "Basilics", note = { { "Un basilic peut passer pour un pan de rocher brisé jusqu'au moment où il bouge. Son corps bas et sa peau épaisse conviennent aux collines sèches de Strangleronce et aux déserts du sud. Les cristaux qui poussent sur les plus vieux spécimens rendent la ressemblance tout à fait convaincante." }, { "Le regard est la difficulté. Ces lézards peuvent figer un adversaire bien vivant comme une statue, si bien que l'affaire ordinaire du naturaliste, regarder de plus près, devient une négociation délicate. Il y a beaucoup à admirer chez un basilic, pourvu qu'il regarde ailleurs." } } },
    ["bats"] = { title = "Chauves-souris", note = { { "Une grotte qui semble vide en plein jour peut avoir un plafond couvert de chauves-souris. Les chauves-souris du crépuscule pendent au-dessus des chemins de Tirisfal, tandis que les passages épineux de Tranchebauge abritent leurs propres colonies. Des ailes occupent une part étonnante d'un tunnel étroit." }, { "Les chauves-souris pestiférées des terres de l'est relèvent d'un récit moins gai. La maladie voyage avec elles à travers un pays déjà ruiné par le Fléau. La silhouette d'une chauve-souris est familière. Ce qu'elle transporte dépend beaucoup de l'endroit où elle a passé la journée." } } },
    ["bears"] = { title = "Ours", note = { { "Des ours noirs de Khaz Modan aux ours Crocs acérés, tout blancs, du Berceau-de-l'Hiver, les ours donnent à une forêt l'air bien habité même quand on n'y voit guère autre chose. Un large dos entre les arbres, une patte lourde sur le chemin, et le sous-bois paraît soudain beaucoup moins vide." }, { "Leur force leur a valu une place dans les arts des druides comme dans les récits des chasseurs. Pour un ours, pourtant, l'affaire du moment est la sienne : manger, garder son territoire, et s'occuper de ce qui vient de s'approcher d'un peu trop près. On peut fort bien en admirer un sans entrer dans cette affaire." } } },
    ["birds"] = { title = "Oiseaux des hauteurs", note = { { "Levez les yeux dans un col de montagne : les ailes au-dessus peuvent être celles d'un hippogriffe, d'une wyverne ou d'un griffon. Les voyageurs rangent volontiers les trois dans la même catégorie. Les bois, les queues à dard et les becs crochus suggèrent qu'un naturaliste devrait se donner un peu plus de peine." }, { "Les hippogriffes portent des cavaliers elfes de la nuit, les griffons sont les compagnons familiers des Wildhammer, et la Horde a ses cavaliers célestes. Au-delà des perchoirs et des aires, leurs cousins sauvages occupent le même ciel. Une selle est une réussite considérable sur une créature qui peut tout simplement s'envoler." } } },
    ["black-dragonflight"] = { title = "Le vol draconique noir", note = { { "Les draconiens noirs habitent un pays marqué par le feu et la pierre brisée. Des dragonnets apparaissent dans les Carmines et les Terres ingrates. Des serviteurs plus grands gardent la forteresse de Nefarian au pic Rochenoire et le repaire d'Onyxia à Âprefange." }, { "La trahison d'Aile de mort pèse sur le vol, tandis que ses enfants poursuivent leurs propres ambitions. Les expériences de Nefarian réunissent des dragons de couleurs différentes dans la même terrible besogne. Un naturaliste habitué à décrire ce qui distingue les vols trouve fort peu de réconfort dans ce que Nefarian essaie d'en faire." } } },
    ["blackrock"] = { title = "Le clan Rochenoire", note = { { "Les orcs Rochenoire tiennent les routes autour de leur montagne aussi bien que les salles qu'elle renferme. Depuis les steppes Ardentes, leurs pillards atteignent les Carmines, où le donjon de Guet-de-pierre rappelle en permanence aux gens de Comté-du-Lac la force du clan." }, { "Rend Blackhand revendique le titre de chef de guerre, même si ses partisans servent sous les ailes de Nefarian. Ils portent les armes et les ambitions de l'ancienne Horde dans un monde où Thrall essaie d'en bâtir une autre. La différence se voit bien avant que le voyageur n'atteigne le Pic." } } },
    ["blighted-elementals"] = { title = "Élémentaires corrompus", note = { { "Les fosses de goudron d'Un'Goro et le sol empoisonné de Gangrebois produisent tous deux des formes mouvantes, mais il ne faut pas leur prêter la même histoire sous le seul prétexte qu'aucune n'est agréable au toucher. Les bêtes du goudron appartiennent au cratère. Les horreurs toxiques appartiennent à une forêt blessée." }, { "Les retombées de Gnomeregan et le fléau des Maleterres ajoutent d'autres exemples à cette page troublée. Chacun porte quelque chose du lieu qui l'a formé. Leurs différences comptent : ce qui sort du sol peut dire au naturaliste ce qui est arrivé au sol lui-même." } } },
    ["blue-dragonflight"] = { title = "Le vol draconique bleu", note = { { "Les draconiens bleus gardent les lieux des arcanes : les vieilles ruines d'Azshara et les salles glacées de Mazthoril. Le vol de Malygos porte depuis longtemps la responsabilité de la magie, ce qui place d'emblée le mortel qui fouille parmi de tels trésors dans une position délicate." }, { "Azuregos veille sur Azshara avec une attitude très personnelle envers les visiteurs. Ses tractations autour d'un vieux registre magique révèlent un certain sens de l'humour. Un devoir ancien ne l'a pas empêché de trouver amusantes les courses d'un aventurier." } } },
    ["boars"] = { title = "Sangliers", note = { { "On trouve des sangliers dans les ravines rouges de Durotar aussi bien que dans les champs verts d'Elwynn. La robe change, et un sanglier des rochers porte un beau pelage contre la neige, mais les défenses dessinent toujours la même silhouette impossible à confondre." }, { "Les Broche-tripes de la Marche de l'Ouest sont un fléau pour les fermes et une précieuse réserve de viande. Le sanglier se trouve donc dans la fâcheuse position d'être prié de quitter le champ pour la marmite, souvent par la même personne. Il s'oppose généralement aux deux." } } },
    ["bronze-dragonflight"] = { title = "Le vol draconique de bronze", note = { { "Les Grottes du temps s'ouvrent sous Tanaris, mais les affaires du vol de bronze s'étendent bien au-delà de ce bout de désert. Les dragons de Nozdormu gardent le temps lui-même, une entreprise pour laquelle la Ligue ne possède aucun instrument de mesure satisfaisant." }, { "Leur rôle dans le scellement d'Ahn'Qiraj appartient à l'histoire écrite. Anachronos veille encore sur le désert à l'entrée des grottes, immense témoin vivant d'une guerre dont les autres traces reposent sous le sable." } } },
    ["burning-blade"] = { title = "La Lame ardente", note = { { "Le nom de la Lame ardente survit sur les lèvres des démonistes et des adorateurs de démons. Ses cultistes occupent des grottes en Durotar et se rassemblent en Désolace. Sous Orgrimmar, le gouffre de Ragefeu met cette allégeance fâcheusement près du nouveau foyer de la Horde." }, { "Le peuple de Thrall s'est battu pour échapper au joug de la Légion. Ces cultistes invitent ses serviteurs à revenir, avec des cercles d'invocation dans le pays même où se sont établis les orcs libérés. Pour un peuple qui retrouve un mode de vie plus ancien, ce sont des voisins particulièrement amers." } } },
    ["burning-legion"] = { title = "La Légion ardente", note = { { "La présence de la Légion change un paysage. À Gangrebois, les arbres en portent les blessures. Dans les Terres foudroyées, les démons occupent le terrain autour de la Porte des ténèbres. Le Convent de Mannoroc et le canyon de la Malechute gardent leurs propres souvenirs vivants de l'invasion." }, { "Ses rangs diffèrent énormément : un gangrechien chasse la magie, un infernal apporte la pierre et la flamme, et un diablotin peut causer une quantité remarquable d'ennuis dans très peu d'espace. Les guerres qui les ont amenés ici sont finies, mais une carte de leurs camps restants est loin d'être vide." } } },
    ["carrion-birds"] = { title = "Charognards", note = { { "Les charognards sont les patients : vautours, busards et condors tournant au-dessus des Tarides, des Terres ingrates et de Mille pointes, attendant que le pays fasse la besogne à leur place. Les déchireurs de la Marche de l'Ouest se sont enhardis depuis que les fermes se sont vidées, et n'attendent pas toujours." }, { "Ils sont un signe qui mérite d'être lu. Un cercle d'entre eux dans le ciel veut dire qu'en dessous quelque chose est mort ou va mourir, et il est parfois sage de savoir quoi avant d'y entrer." }, { "Les rocs du grand sud sont une autre affaire : de grands rapaces qui chassent du gibier vivant, et qui traitent le voyageur comme tel." } } },
    ["centaurs"] = { title = "Centaures", note = { { "Les clans centaures occupent les terres ouvertes de Kalimdor, leurs villages et leurs bandes de guerre dispersés dans les Tarides, en Désolace et à Mille pointes. Les taurens les connaissent comme des poursuivants depuis des générations. En Désolace, les noms Gelkis, Magram et Maraudine désignent des revendications rivales autant que des camps différents." }, { "Un voyageur peut marchander avec certains de ces clans, même si l'amitié de l'un risque de coûter celle d'un autre. Leurs chamans parlent de la terre, et Theradras a ses fidèles parmi eux. Il y a là plus qu'un raid aperçu depuis la route." }, { "Leur ascendance remonte à Theradras et à Zaetar, le fils de Cenarius que ses propres enfants ont tué. Maraudon garde cette histoire de famille sous une forme particulièrement malheureuse." } } },
    ["chimaeras"] = { title = "Chimères", note = { { "Deux têtes sur un même corps ailé rendent une chimère reconnaissable entre toutes, avant même que son souffle ne frappe. Les elfes de la nuit ont combattu aux côtés de ces créatures, dont la force et le souffle corrosif sont redoutables contre la pierre comme contre la chair." }, { "Le Berceau-de-l'Hiver en abrite une espèce pâle et hirsute, faite pour la neige. Au large de Feralas, l'île de l'Effroi cache les énormes chimaeroks. Sur une carte, c'est une petite île. Un chimaerok donne au voyageur toutes les raisons de se demander combien il en reste entre la bête et le rivage." } } },
    ["crabs"] = { title = "Crabes", note = { { "Un crabe promène une petite forteresse le long du rivage. La carapace règle l'essentiel de la discussion, les pinces s'occupent du reste, et l'ensemble se déplace de côté avec une assurance admirable." }, { "Clampants des sables et clampants de l'écume occupent les plages des deux continents. Les cuisiniers apprécient leur chair, tandis qu'une étendue de sable tranquille offre au naturaliste un spectacle qui vaut d'être observé : une créature qui vaque à ses affaires à la frontière de la terre et de la mer. Tout ce qui se trouve sur une plage n'attend pas un navire." } } },
    ["crocolisks"] = { title = "Crocilisques", note = { { "Les crocilisques sont des créatures anciennes, aux longues mâchoires et à l'armure épaisse, qui ont survécu à des empires par la simple méthode consistant à rester immobiles dans l'eau tiède et à manger ce qui vient y boire. Ils hantent les lochs de Khaz Modan, les fondrières des Paluns, les rivières de Strangleronce et les rives d'Âprefange." }, { "Un crocilisque sur la berge a l'air endormi. Il ne l'est pas. Il peut couvrir la distance qui le sépare d'un voyageur imprudent plus vite qu'il ne semble convenable pour une bête aussi lourde." }, { "Leur peau fait un beau cuir, et leur viande est meilleure qu'elle n'a le droit de l'être. Ni l'une ni l'autre ne vaut qu'on y laisse une jambe." } } },
    ["cult-of-the-damned"] = { title = "Le Culte des damnés", note = { { "Parmi les morts du Fléau se tiennent des gens encore vivants. Le Culte des damnés fournit nécromanciens, acolytes et mains volontaires à une armée qui devrait autrement fabriquer toutes ses recrues." }, { "La Scholomance, sous Caer Darrow, donne à ces arts une école, où les leçons se donnent parmi les restes de Lordaeron. Ailleurs, le culte entretient des chaudrons de peste et relève les morts. Un érudit vivant à son bureau devrait être une vue rassurante. Ici, c'est l'objet de l'étude qui change tout." } } },
    ["dark-iron-dwarves"] = { title = "Nains Sombrefer", note = { { "Le travail des Sombrefer est indiscutablement nain : des mines profondes, de lourdes fortifications et des machines bâties pour survivre à leurs fabricants. La place forte du clan sous le mont Rochenoire est une cité autant qu'une forteresse, avec des forges, une arène et la cour d'un empereur." }, { "La guerre des Trois Marteaux les a laissés ennemis de Forgefer. L'invocation de Thaurissan les a laissés sujets de Ragnaros. Leurs agents travaillent désormais bien au-delà de la montagne, dans des carrières et des camps à travers tout Khaz Modan." }, { "La poudre noire et la belle maçonnerie sont des choses familières entre les mains d'un autre nain. C'est la direction du canon qui rend cette page difficile." } } },
    ["defias"] = { title = "La Confrérie défias", note = { { "Un masque rouge peut désigner un vide-gousset sur une route d'Elwynn ou un artisan au travail sous les Mortemines. La Confrérie défias est née du travail impayé des Tailleurs de pierre qui ont rebâti Hurlevent, et Edwin VanCleef a porté ce grief jusqu'à la Marche de l'Ouest." }, { "Les fermes souffrent aujourd'hui d'une querelle que leurs propriétaires n'ont pas réglée. Sous Ruisselune, la Confrérie a organisé bien plus qu'un brigandage de grand chemin : des ateliers, des gros bras à gages et un navire. Le savoir-faire des maçons a survécu. La cité qu'il devait servir est devenue leur cible." } } },
    ["dragonmaw"] = { title = "Le clan Dragonmaw", note = { { "Les Dragonmaw ont jadis mené des dragons rouges à la guerre en gardant Alexstrasza captive à Grim Batol. La libération de la reine a brisé ce pouvoir, mais le clan a toujours des camps dans les Paluns, où ses étendards sont un danger familier le long des routes." }, { "Leurs raids appartiennent aux guerres résiduelles de l'ancienne Horde. Grim Batol elle-même est désormais gardée par le vol rouge, rappel imposant que le clan a autrefois détenu une captive bien plus grande que tout prisonnier que ses derniers guerriers pourraient faire." } } },
    ["druids-of-the-fang"] = { title = "Les druides du Croc", note = { { "Naralex est entré dans les Cavernes des lamentations dans l'espoir de rendre les Tarides à la vie par le Rêve d'émeraude. Il y dort encore, et le cauchemar qui l'a pris a changé à la fois les bêtes de la caverne et ses disciples." }, { "Les druides du Croc portent des noms de serpent et prennent des formes de serpent : Cobrahn, Anacondra, Pythas et Serpentis. Leurs rites occupent des grottes qui devaient être le commencement d'une terre plus verte. L'eau et la végétation abondent sous les Tarides. Le problème, c'est ce qui a poussé avec elles." } } },
    ["earth-elementals"] = { title = "Élémentaires de terre", note = { { "Les élémentaires de terre apportent la colline avec eux : de lourdes formes de roche qui se meuvent dans les Terres ingrates, des corps d'obsidienne dans les terres brûlées autour de Rochenoire. La distinction entre un rocher et un habitant peut être de courte durée." }, { "Uldaman contient aussi des gardiens des pierres, des créations qui gardent un lieu bâti plutôt que des esprits sauvages errant en terrain découvert. Pour la Ligue, la différence est considérable. Un élémentaire de roche peut être un trait du paysage. Un gardien de pierre est la preuve que quelqu'un avait quelque chose à protéger." } } },
    ["earthen"] = { title = "Les Terrestres", note = { { "Les terrestres sont des êtres de pierre vivante, faits par les titans pour façonner les profondeurs du monde, et à Uldaman certains d'entre eux arpentent encore les salles de la chambre forte des titans, la gardant comme ils ont été faits pour le faire." }, { "Les disques de platine de cette chambre disent que les nains descendent d'eux. Ce sont, au sens le plus simple, mes ancêtres, et ils essaieront de vous tuer." }, { "Je les consigne avec un respect que je ne m'explique pas tout à fait, et une prudence que je m'explique très bien." } } },
    ["faerie-dragons"] = { title = "Dragons féériques", note = { { "Un dragon féérique apporte des ailes vives et un petit corps rapide dans les vieilles forêts de Kalimdor. Malgré son nom et sa place sur cette page, ce n'est pas un petit membre de l'un des grands vols draconiques." }, { "Ces créatures ont des liens avec le Rêve d'émeraude et un rapport singulier à la magie. Les elfes de la nuit les connaissent comme des alliés de la forêt. L'espèce déviante des Cavernes des lamentations appartient à un cadre bien moins heureux. La couleur seule rend mal compte de ce qui est arrivé à une créature là-dedans." } } },
    ["fire-elementals"] = { title = "Élémentaires de feu", note = { { "Des flammes vivantes parcourent le pays brûlé autour du mont Rochenoire et les pentes du volcan d'Un'Goro. Un élémentaire de feu donne au mouvement familier d'un brasier une direction et une volonté propres." }, { "Ragnaros règne sur les feux les plus profonds sous Rochenoire, avec des serviteurs dans tout son domaine. Ailleurs, chamans et invocateurs appellent la flamme dans d'autres cadres. L'élément reste reconnaissable, mais sa seule présence ne dit pas au voyageur aux ordres de qui il obéit, s'il obéit à quelqu'un." } } },
    ["forest-trolls"] = { title = "Trolls des forêts", note = { { "Les Witherbark, les Vilebranch et les Mossflayer occupent des forêts où se superposent les restes d'une ancienne domination trolle. Jintha'Alor reste une redoutable cité-temple, ses terrasses gravissant les Hinterlands au lieu de s'y enfoncer tranquillement." }, { "Les Amani ont combattu Quel'thalas bien avant que les royaumes humains actuels ne prennent forme. Cette longue rivalité survit parmi des tribus dont les fortunes diffèrent aujourd'hui grandement. Les Revantusk commercent avec la Horde sur la côte des Hinterlands, tandis que leurs voisins tiennent leur propre terrain à l'intérieur des terres." }, { "La peau verte et les défenses identifient assez facilement un troll des forêts. Elles ne disent pas au voyageur quel accueil attendre." } } },
    ["furbolgs"] = { title = "Furbolgs", note = { { "Les villages furbolgs appartiennent aux vieilles forêts de Kalimdor. Totems, abris et chamans leur donnent une place parmi les peuples de la forêt, même si le voyageur qui arrive dans un camp corrompu n'en voit peut-être que la violence." }, { "Les Pin-tordu, les Noirbois, les Mort-bois et les Tombe-hiver ont tous subi de terribles changements. Les Grumegueules ont résisté à ce sort et gardent toujours leurs tunnels entre Gangrebois, Reflet-de-Lune et le Berceau-de-l'Hiver. Leur méfiance envers les étrangers a d'amples raisons." }, { client = "forever", "Le repaire des Noiregueules, en Azshara, appartient à une autre tribu. La corruption y a pris racine elle aussi. Les Grumegueules de Gangrebois ne doivent pas porter le blâme de ce qui se trouve derrière sa porte de pierre." } } },
    ["giants"] = { title = "Géants", note = { { "Des géants des mers arpentent les côtes de Kalimdor, et de grands marcheurs des falaises occupent les hauteurs d'Azshara et de Feralas. Contre un promontoire lointain, leur taille peut être difficile à juger. Un arbre ou une colonne en ruine à côté d'eux fournit la mesure qui manque." }, { "Les récits rattachent les géants du monde à son façonnement ancien. La Ligue a encore beaucoup à établir sur leurs différentes espèces. Pour un arpenteur, leurs traces mêmes sont des accidents de terrain notables, et un spécimen vivant peut interrompre une vue très étendue." } } },
    ["gnolls"] = { title = "Gnolls", note = { { "Les camps de gnolls se pressent autour des mines, des champs et des routes mal gardées. Les tentes des Rivepatte en Elwynn et dans la Marche de l'Ouest, les huttes des Poil-moussu dans les Paluns et les camps des Griffebois en Feralas présentent à peu près le même avantage pratique : les provisions des autres à portée de main." }, { "Leurs meutes ont des chefs, des lanceurs de sorts et des pillards, et peuvent mettre un village sous une réelle pression. La réputation de Lardeur a voyagé bien au-delà de son bout d'Elwynn. C'est une distinction inhabituelle pour un gnoll, même si ceux qui paient sa prime la verraient volontiers prendre fin." } } },
    ["goblins"] = { title = "Gobelins", note = { { "Les gobelins consignés ici se rencontrent sur le sol d'un atelier ou d'un champ de bataille plutôt que derrière le comptoir d'une boutique. VanCleef a des ingénieurs dans les Mortemines, et des inventions dangereuses apparaissent partout où leurs fabricants trouvent de la place pour travailler." }, { "Un déchiqueteur ou un garde à gages en dit long sur les moyens qui se cachent derrière un petit camp gobelin. Une bonne part du combat peut être assurée par quelque chose que l'ingénieur a construit, acheté ou persuadé de se tenir devant lui. La taille de l'inventeur donne une piètre mesure de l'ampleur de l'entreprise." } } },
    ["gorillas"] = { title = "Gorilles", note = { { "Les gorilles de Strangleronce, de Feralas et d'Un'Goro ont la carrure qu'il faut pour se faire remarquer dans une jungle encombrée. Dos argentés, gorilles de Valbrume et grands Foudroyeurs diffèrent par la taille, mais même les plus petits font paraître minces les troncs autour d'eux." }, { "Leurs noms disent quelque chose de l'impression qu'ils laissent : Roi Mukla, Uhk'loc, U'cha. Des chasseurs partent à la recherche d'une bête précise et reviennent avec un nom qui sonne comme celui d'un souverain. Un gorille n'a besoin ni de couronne ni de trône pour occuper une clairière de fond en comble." } } },
    ["great-cats"] = { title = "Grands félins", note = { { "Les grands félins donnent à une forêt une bonne part de son silence. La robe sombre d'un sabre-de-nuit disparaît entre les arbres de Teldrassil, un sabre-de-givre appartient à la neige du Berceau-de-l'Hiver, et une panthère de Strangleronce peut être remarquablement difficile à repérer en plein jour." }, { "Le lien des elfes de la nuit avec leurs sabres montre une autre facette de ces chasseurs : compagnons et montures autant que prédateurs. Hors des bêtes dressées, la même grâce sert les affaires de la chasse. Un tigre qui traverse un chemin ensoleillé est un beau spectacle, si bref soit-il." } } },
    ["great-saurians"] = { title = "Diablosaures et bêtes d'Un'Goro", note = { { "Un'Goro a de la place pour des créatures qui rendraient la plupart des autres forêts exiguës. Les diablosaures avancent au-dessus du sous-bois, les stégodons portent de grandes plaques le long du dos, et les pterreurdactyles tournent au-dessus des bords du cratère. Un dimeurtrodon près des sources chaudes peut sembler presque modeste en pareille compagnie." }, { "L'expédition Marshal a donné un nom à ces bêtes et une place dans ses rapports. Le cratère leur donne le reste : une végétation dense, un sol fumant, et assez d'espace pour qu'un diablosaure disparaisse derrière le prochain bosquet. En dresser l'inventaire est une entreprise considérable." } } },
    ["green-dragonflight"] = { title = "Le vol draconique vert", note = { { "Le vol vert d'Ysera garde le Rêve d'émeraude, mais le Cauchemar a atteint certains de ses propres gardiens. Les draconiens des grands portails d'Ashenvale, de Feralas, des Hinterlands et du bois de la Pénombre rendent ce danger visible dans le monde éveillé." }, { "L'ombre d'Eranikus hante le Temple englouti, et d'autres dragons puissants sont sortis du Rêve changés. Les grands arbres autour des portails restent beaux. C'est en partie ce qui rend la corruption si troublante : l'entrée d'un lieu de vie s'est trouvé des gardiens si tourmentés." } } },
    ["grimtotem"] = { title = "Le Totem sinistre", note = { { "Les camps du Totem sinistre occupent des positions dominantes : la cime de Noir-nuage au-dessus de Mille pointes, une enceinte en Feralas, et d'autres possessions plus loin à travers Kalimdor. Leurs guerriers et leurs chamans ont la force des autres taurens, tournée contre des voisins qui partagent souvent leur ascendance." }, { "Magatha Grimtotem a sa place parmi les anciens de Thunder Bluff, alors même que les ambitions de sa tribu l'opposent à la voie de Cairne. Les totems et les tentes familiers peuvent faire passer un camp hostile, à tort, pour un refuge au bord de la route." } } },
    ["harpies"] = { title = "Harpies", note = { { "Les harpies font leurs nids au-dessus des approches des villages des autres. Les perchoirs des Terrevent en Durotar, les hauteurs des Furie-des-vents en Mulgore et les nids des Ensorçaile dans les Tarides donnent tous l'avantage aux ailes sur une caravane." }, { "Leurs serres ne sont qu'une partie du danger. Les sorcières des tempêtes ajoutent des sorts aux cris d'une volée dérangée. Un nid haut perché sur une falaise est un endroit difficile à atteindre avec des questions. Une grande partie de ce que la Ligue sait des harpies a donc été recueillie depuis le sol, en contrebas." } } },
    ["hostile-elves"] = { title = "Elfes hostiles", note = { { "Une expédition elfe parmi les ruines peut chercher les mêmes choses que la Ligue : une inscription, une relique, un vestige d'un artisanat ancien. En Azshara, la quête des elfes de sang pour un pouvoir arcanique perdu fait de cet intérêt commun une bien piètre garantie d'accueil." }, { "Hache-tripes a ses propres étudiants en magie dangereux, Lethtendris parmi eux. Les vieilles cités contiennent encore un pouvoir qui vaut d'être cherché, et ceux qui l'atteignent ne laissent pas toujours de place à un second érudit." } } },
    ["hydras"] = { title = "Hydres", note = { { "Une hydre s'annonce plusieurs têtes à la fois. Les longs cous se dressent hors de l'eau côtière ou d'un bassin de caverne, et il devient difficile de décider quelle paire d'yeux mérite d'abord l'attention." }, { "Les Fouettebrume hantent les côtes de Kalimdor, tandis que d'autres hydres vivent au fond de Maraudon. Gahz'rilla a un bassin sacré à Zul'Farrak et le culte des Sandfury. La plupart des créatures de ce livre doivent se contenter d'un terrain de chasse. Celle-là s'est acquis une congrégation." } } },
    ["hyenas"] = { title = "Hyènes", note = { { "Les hyènes vont bien au pays sec : des silhouettes maigres contre la poussière des Tarides, de Tanaris et de Désolace. Leurs cris les trahissent même quand l'herbe ou un pli du terrain cache la meute." }, { "Les noms qu'on leur donne sont rarement affectueux. Raillecroc, Brûlepatte, hyène affamée : les voyageurs se souviennent du bruit, des dents ou de l'état de la bête qui les a suivis. Il y a toute une vie difficile dans ce dernier nom, là-bas où un repas n'est jamais assuré." } } },
    ["ice-trolls"] = { title = "Trolls des glaces", note = { { "Les Frostmane connaissent Dun Morogh comme une patrie plutôt que comme une route vers Forgefer. Leur repaire à l'ouest de Kharanos et leurs camps dans la neige restent proches des villages nains qui les ont chassés d'une grande partie de la vallée." }, { "Chasseurs de têtes, voyants et exhalombres défendent ce qu'ils possèdent encore. Pour un jeune nain, ce sont souvent les premiers trolls ennemis rencontrés. Pour les Frostmane, le nain est un nouvel arrivant de plus venu de la cité d'en haut. Le même col enneigé porte deux récits très différents de qui y est chez soi." } } },
    ["insects"] = { title = "Insectes", note = { { "Tous les grands insectes n'appartiennent pas à une ruche silithide. Les scarabées et autres coléoptères habitent les déserts et les vieilles ruines de plein droit, même si leur taille pousse parfois le voyageur à chercher une arme avant son carnet." }, { "À Zul'Farrak, les scarabées circulent parmi la maçonnerie et les lieux de sépulture des Sandfury. Contre le mur d'un temple, ils semblent un détail. Rassemblés autour de vos bottes, ils réclament beaucoup plus d'attention." } } },
    ["jungle-trolls"] = { title = "Trolls de la jungle", note = { { "Les ruines trolles de Strangleronce sont une histoire habitée. Les tribus Bloodscalp et Skullsplitter se battent parmi les vieilles pierres, tandis que Zul'Gurub reste un centre du pouvoir gurubashi. Ses grands prêtres ont ramené Hakkar dans le monde." }, { "Les Atal'ai portent aussi le culte du dieu du sang jusqu'au Temple englouti. D'autres trolls de la jungle ont pris une autre voie : les Darkspear appartiennent à la Horde de Thrall, et l'île de Yojamba abrite l'effort de Zandalar contre Hakkar. Un vieil empire a laissé de nombreux héritiers, aux desseins très différents." } } },
    ["kobolds"] = { title = "Kobolds", note = { { "Une lumière dans une mine abandonnée appartient souvent à un kobold. Leurs bougies marquent les tunnels d'Elwynn et de la Marche de l'Ouest, où des passages étroits permettent à un petit creuseur de devenir une grosse nuisance." }, { "La protestation familière, \"Toi pas prendre bougie !\", est tout à fait claire sur le sujet le plus pressant. Au-delà, la bougie raconte une histoire pratique : quelqu'un a l'intention de travailler et de vivre dans le noir. Pour le mineur qui revient réclamer sa concession, le tunnel est occupé. Pour le kobold, l'intrus, c'est le mineur." } } },
    ["kodos"] = { title = "Kodos", note = { { "Les troupeaux de kodos donnent aux plaines un rythme lent et lourd. Les taurens voyagent et combattent aux côtés de ces grandes bêtes, et un kodo chargé est un spectacle familier partout où la Horde a une longue route à parcourir." }, { "Désolace abrite un rassemblement plus étrange : le Cimetière des kodos, où les bêtes âgées viennent mourir parmi les os des leurs. Les troupeaux vivants impressionnent, mais ces restes immenses en donnent une autre mesure. Une créature si intimement liée à une caravane en marche peut laisser derrière elle un lieu parfaitement immobile." } } },
    ["leper-gnomes"] = { title = "Gnomes lépreux", note = { { "La chute de Gnomeregan n'a pas envoyé tous les survivants à Forgefer. Les radiations ont changé, dans leur corps et leur esprit, certains de ceux qui étaient restés dans la cité, et les gnomes lépreux habitent toujours ses abords et ses salles pleines de machines." }, { "Leur peau verte rend le mal visible d'emblée. Les vêtements et les outils gnomes familiers rendent son sens plus difficile à écarter. Pour les exilés, la vieille cité contient des voisins autant que les choses qui les en ont chassés." } } },
    ["living-plants"] = { title = "Plantes vivantes et Anciens", note = { { "Une forêt peut bouger sans un souffle de vent. Tréants et Anciens donnent aux bois des elfes de la nuit leurs grandes formes marchantes, tandis que flagellants et rampants occupent un terrain bien plus proche des bottes du voyageur." }, { "Certains défendent un bois vivant. D'autres ont été changés par la corruption. Les sylvains de Teldrassil et la végétation de Hache-tripes méritent des récits différents, même quand les uns comme les autres rendent un chemin difficile à franchir." }, { "Le marais a ses propres formes de végétation et de boue mouvantes. Racines, branches et une couleur verte familière ne sont que le début de l'identification de ce qui s'en est levé." } } },
    ["lost-ones"] = { title = "Les Perdus", note = { { "Les draeneï du Havre boueux sont des réfugiés de Draenor, le monde d'où sont venus les orcs. Les Perdus du Sanctuaire des friches partagent cette origine, même si leur isolement violent rend le lien moins évident au voyageur qui traverse le marais." }, { "Magtoor et ses compagnons offrent leur aide quand ils le peuvent, parmi des gens qui ne savent guère quoi penser d'eux. Leur présence donne au camp des Perdus un contexte plus triste : c'est un autre peuple dispersé loin de chez lui, dont certains ne peuvent plus trouver refuge parmi les autres." } } },
    ["machines"] = { title = "Golems et machines", note = { { "Un golem des moissons dans les champs de la Marche de l'Ouest relève d'une tout autre sorte de nature. Les déchiqueteurs des Serres-Rocheuses, les machines de guerre de Gnomeregan et les créations des Sombrefer sont tous sortis d'un atelier, quoi qu'il soit advenu de leurs instructions depuis." }, { "Les intentions de leurs fabricants peuvent survivre dans le dessin : des bras qui tranchent, des pinces à moissonner, un canon placé là où un animal aurait une tête. La machine n'a pas besoin de s'expliquer. Un observateur peut souvent lire sa fonction dans les outils qui y sont fixés." } } },
    ["makrura"] = { title = "Makrura", note = { { "Les makrura occupent les hauts-fonds de Kalimdor avec une présence bien différente de celle des crabes qui les côtoient. Les corps dressés, les pinces préhensiles et les colonies gardées appartiennent à un peuple, si peu familiers que soient leur langue et leur forme." }, { "Le rivage de Durotar offre à bien des jeunes orcs leur première rencontre avec eux. De plus grandes colonies se trouvent plus bas sur la côte. Une plage offre peu de couvert au voyageur qui arrive par la terre, et un village makrura ne s'arrête pas forcément au bord de l'eau." } } },
    ["murlocs"] = { title = "Murlocs", note = { { "Les villages murlocs laissent une marque reconnaissable sur un rivage : des huttes basses, des filets de pêche et beaucoup de bruit à l'approche d'un étranger. Leurs outils et leurs villages méritent plus d'attention que ne leur en accordent les récits habituels d'une charge gargouillante." }, { "Ils défendent ces villages ensemble, ce qui explique qu'un combat commencé avec l'un d'eux puisse s'étendre si vite le long d'une plage. Leur langue est difficile à comprendre pour la plupart des voyageurs. C'est une difficulté de traduction, pas la preuve que rien n'est dit." } } },
    ["naga"] = { title = "Nagas", note = { { "Les nagas occupent des lieux engloutis qui faisaient autrefois partie du monde des elfes de la nuit : la grève de Zoram, les ruines d'Azshara et la côte de Sombrivage. Leurs corps serpentins conviennent désormais à l'eau qui a recouvert l'ancien domaine des Bien-nés." }, { "Ils sont apparus au grand jour après la Troisième Guerre et se sont établis depuis sur bien des rivages. Sorcières des mers et myrmidons armés en font plus que des camps de plage épars. Parmi les colonnes brisées, ils peuvent sembler être revenus dans une cité dont eux seuls peuvent encore emprunter les rues." } } },
    ["oddities"] = { title = "Créatures étranges", note = { { "Certaines rencontres font paraître bien insuffisants les titres d'une histoire naturelle. Un monstre singulier, un étrange habitant de donjon ou une créature honorée par un culte local peuvent n'avoir aucune parenté utile ailleurs dans ce livre." }, { "Cette page garde la rencontre telle quelle tant que sa place dans le récit d'ensemble reste incertaine. Il y a de la place dans un carnet de terrain pour une question sans réponse, surtout quand elle vient de sortir d'un lac." } } },
    ["ogres"] = { title = "Ogres", note = { { "Les ogres sont passés par la Porte des ténèbres avec la Horde, puis se sont dispersés en clans à travers Azeroth. Une tour en ruine ou une grotte de montagne peut aujourd'hui abriter des Rochepoing, des Cassecrête, des Crache-poussières ou un autre clan dont le nom est devenu un avertissement local." }, { "Leur taille est la première chose qu'on remarque, mais les ogres-mages font de piètres sujets pour les plaisanteries habituelles sur l'intelligence des ogres. Deux têtes peuvent porter une redoutable maîtrise de la magie." }, { "Les Cognepierre d'Âprefange ont rejoint la Horde. Ailleurs, il faut apprendre clan par clan où vont leurs loyautés. Une silhouette familière ne tient pas lieu de présentation." } } },
    ["oozes"] = { title = "Limons et vases", note = { { "Un limon n'a guère de forme pour aider le naturaliste à le décrire. La couleur et la consistance doivent faire l'essentiel du travail : les vases d'un marais, les étranges restes du désastre de Gnomeregan, la fange mouvante des eaux empoisonnées." }, { "Certains laissent les restes de ce qu'ils ont avalé, un témoignage peu ragoûtant mais utile sur leur environnement. On les néglige facilement à côté d'une grande bête ou d'un arbre qui marche. Une flaque de vase qui remonte la pente a pourtant sa place dans le carnet." } } },
    ["other-beasts"] = { title = "Autres bêtes", note = { { "Il est des bêtes pour lesquelles un joli titre de famille promettrait plus que les preuves ne le permettent. Une forme inhabituelle, un spécimen solitaire, une créature connue surtout par le nom inscrit sur la commande d'un chasseur peuvent trouver leur place ici." }, { "Un vaste catalogue est utile jusqu'au moment où il cache l'animal qu'il contient. Ces fiches laissent de la place à l'individu : où on l'a rencontré, à quoi il ressemblait, et ce qui le distingue du dernier monstre prétendument unique." } } },
    ["other-dragonkin"] = { title = "Autres draconiens", note = { { "La couleur d'un dragon offre d'ordinaire un point de départ à son histoire. Elle aide moins devant un spécimen inconnu, ou devant les draconiens mêlés que produisent les expériences de Nefarian au pic Rochenoire." }, { "Ces créatures sont consignées ici jusqu'à ce qu'il y ait une bonne raison de les placer ailleurs. Un catalogue bien rangé ne devrait pas dissimuler une identification difficile, surtout quand la créature en question est assez grande pour protester contre le retard." } } },
    ["other-elementals"] = { title = "Autres élémentaires", note = { { "Les divisions familières de la terre, de l'air, du feu et de l'eau ne règlent pas toutes les rencontres. Certains êtres animés et certaines formes élémentaires inhabituelles arrivent sur cette page sans place claire parmi les autres." }, { "Leur cadre fournit souvent le meilleur point de départ : la salle d'un invocateur, un ancien palais, un étrange bout de pays découvert. La fiche peut conserver ces détails même là où la nature de l'habitant reste incertaine." } } },
    ["other-peoples"] = { title = "Autres humanoïdes", note = { { "Certains adversaires se consignent le mieux par le lieu et la compagnie où on les a rencontrés. Un hors-la-loi solitaire, le garde d'un donjon et un magicien renégat peuvent partager une race sans partager aucune cause." }, { "Ces pages gardent leurs rencontres ensemble sans leur inventer de bannière. Un nom, une arme et un camp sont de modestes débuts pour un récit, mais cela vaut mieux que de laisser une personne inconnue disparaître dans le mot \"ennemi\"." } } },
    ["other-undead"] = { title = "Autres morts-vivants", note = { { "La peste de Lordaeron n'explique pas tous les cadavres qui marchent. Le bois de la Pénombre a des tombes troublées par d'autres mains, et de vieilles malédictions ou l'ouvrage d'un nécromancien peuvent laisser des morts en mouvement loin des armées du Fléau." }, { "Un nom peut avoir ici une valeur toute particulière. Les restes ont pu survivre à l'explication, alors qu'un registre de village ou un parent encore en vie la conserve. La créature du cimetière et la personne du récit sont parfois un seul et même sujet, abordé par les deux bouts opposés d'une histoire." } } },
    ["owls"] = { title = "Chouettes et hiboux", note = { { "Une chouette se trouve souvent le plus facilement par ses yeux. Les hiboux Strigid de Teldrassil se tiennent dans une forêt déjà pleine de la vigilance des elfes de la nuit, tandis que les grandes chouettes du Berceau-de-l'Hiver se détachent, pâles, sur les arbres sombres." }, { "Les chouettes Bec-de-fer de Gangrebois appartiennent à une forêt abîmée, et en partagent les dangers. Ailleurs, on a le loisir d'apprécier l'immobilité d'un oiseau perché avant que les ailes ne s'ouvrent. Les forêts contiennent bien assez de bruit. Une chouette offre un excellent sujet d'observation dans le silence." } } },
    ["pirates"] = { title = "Pirates", note = { { "Un camp de pirates ressemble beaucoup à un port : des navires, des réserves et des marins qui ont du travail. La différence apparaît quand un navire de la Voile sanglante fond sur Baie-du-Butin, ou quand des équipages des Mers du sud font main basse sur une autre cargaison." }, { "Leurs repaires parsèment les côtes chaudes, de la côte des Marchands jusqu'à Tanaris. Le commerce gobelin a rendu ces eaux assez fréquentées pour faire vivre à la fois les marchands et ceux qui les volent. Depuis un promontoire lointain, les voiles se ressemblent beaucoup." } } },
    ["quilboar"] = { title = "Hurans", note = { { "Les immenses épines des Tarides sont une patrie pour les hurans. Leurs traditions nomment Agamaggan comme ancêtre, et la présence du demi-dieu tombé appartient à la terre autant qu'à leurs rites." }, { "Les camps Tranchecrin, Dos-hirsute et Tranchebauge défendent ce pays contre les taurens, les centaures et la nouvelle Horde. Leurs chamans donnent aux villages épineux une autre sorte de force. Aux Souilles de Tranchebauge, des tractations avec le Fléau ont entraîné la tribu de la Tête de Mort dans une allégeance plus sombre." }, { "Un étranger voit un mur de ronces. Derrière, il y a des foyers, des tribus rivales et une histoire plus ancienne que la route qui passe." } } },
    ["rams-and-goats"] = { title = "Béliers et chèvres", note = { { "Un bélier a l'air parfaitement chez lui sur un terrain qui pousse un nain à s'interroger sur la qualité de ses bottes. L'épaisse toison et les cornes recourbées sont familières dans tout Khaz Modan, et les bêtes montées au départ de Forgefer ont des cousins sauvages dans les mêmes montagnes." }, { "Les Foudrepique se tournent eux aussi vers les béliers dans la vallée d'Alterac. Entre un sentier de montagne et un champ de bataille, le pied d'une monture est mis à rude épreuve. Le bélier aborde l'un et l'autre avec l'expression d'un animal qui a déjà trouvé le terrain satisfaisant." } } },
    ["raptors"] = { title = "Raptors", note = { { "Un raptor n'est que pattes arrière, queue et dents, bâti sur des lignes qui ne ressemblent en rien à celles d'un loup ou d'un félin. Les Griffesang de Durotar et les solécailles des Tarides en sont des exemples familiers. Des espèces plus grandes chassent dans les Paluns et les jungles du sud." }, { "Les cavaliers trolls en ont fait des compagnons, une pratique qui demande une grande confiance en l'animal qui vous porte. À l'état sauvage, la silhouette étroite d'un raptor peut se perdre dans les roseaux jusqu'à ce qu'il se retourne. La tête est généralement ce dont le voyageur se souvient en premier." } } },
    ["red-dragonflight"] = { title = "Le vol draconique rouge", note = { { "Des dragonnets rouges habitent encore les Paluns, où les plus grands membres du vol d'Alexstrasza gardent Grim Batol. La montagne a jadis tenu leur reine captive sous la coupe des orcs Dragonmaw, qui se servirent de sa progéniture pendant la Deuxième Guerre." }, { "Sa libération a mis fin à cette captivité sans faire de Grim Batol un lieu accueillant. Les draconiens rouges en gardent désormais les abords contre les étrangers. Pour un vol chargé de protéger la vie, ces portes gardées portent un souvenir long et amer." } } },
    ["restless-spirits"] = { title = "Fantômes et esprits sans repos", note = { { "Tous les fantômes d'Azeroth ne servent pas le Fléau. Certains sont des esprits qui n'ont jamais trouvé le repos : les Bien-nés qui hantent leurs tours en ruine à Sombrivage et en Azshara, les noyés et les assassinés, les guerriers tombés loin de chez eux et qui errent encore." }, { "Certains sont seulement tristes. D'autres sont en colère, et la colère est tout ce qui reste d'eux. Quelques-uns parlent, si l'on écoute." }, { "La Ligue les consigne avec soin. Ce sont, après tout, les plus vieux témoins que nous ayons." } } },
    ["sand-trolls"] = { title = "Trolls des sables", note = { { "Zul'Farrak se dresse encore au-dessus du sable comme une cité, malgré toutes les ruines alentour. Les Sandfury défendent ses terrasses et ses bassins sacrés contre un désert de plus en plus encombré de gobelins, de bandits et d'aventuriers." }, { "Gahz'rilla y est vénéré, et les tombeaux ont des gardiens qui ne sont pas restés morts. La cité est un mauvais terrain pour traiter chaque vieille pierre comme une relique abandonnée. Les descendants de ses bâtisseurs sont tout à fait capables de disputer à un visiteur ses prétentions sur l'une d'elles." } } },
    ["satyrs"] = { title = "Satyres", note = { { "Un camp de satyres est une plaie dans une vieille forêt. Des silhouettes cornues circulent parmi des arbres malades, et les elfes de la nuit qui s'y opposent combattent des créatures dont l'histoire a commencé parmi leur propre peuple." }, { "Xavius, le conseiller de la reine Azshara, fut le premier des satyres, refaçonné par Sargeras pendant la guerre des Anciens. Leur engeance sert encore la corruption en Ashenvale et à Gangrebois. Dix mille ans ont passé, et pourtant la forêt perd toujours du terrain autour de leurs camps." } } },
    ["scarlet-crusade"] = { title = "La Croisade écarlate", note = { { "Les bannières rouges de la Croisade écarlate marquent certaines des plus solides positions humaines qui subsistent en Lordaeron : le monastère, Âtreval, la Main de Tyr et une partie de Stratholme. Prêtres, paladins et soldats tiennent ces murs contre les morts-vivants." }, { "Leur méfiance va bien au-delà du Fléau. Les étrangers peuvent être traités en porteurs de peste ou en ennemis déguisés, et les Réprouvés n'ont aucune place dans leur idée d'un royaume restauré. Un voyageur peut trouver des défenseurs vivants derrière les barricades sans y trouver de refuge." } } },
    ["scorpids"] = { title = "Scorpides", note = { { "Les scorpides tirent un parti remarquable du sol sec. Leurs carapaces basses se fondent dans la terre rouge de Durotar et la poussière des déserts du sud, et la queue dressée n'apparaît qu'un instant plus tard, ce qui est déconcertant." }, { "Leur venin et leur armure ont tous deux leur usage, ce qui envoie les jeunes chasseurs à la recherche des créatures contre lesquelles leurs aînés les ont mis en garde. Les orcs de Durotar connaissent bien les carapaces de scorpide. Un spécimen étendu pour l'étude est une belle pièce d'armure naturelle, aux articulations qui récompensent un examen attentif." } } },
    ["scourge"] = { title = "Le Fléau", note = { { "Le Fléau fait d'une population une armée : squelettes, goules, victimes de la peste et abominations recousues remplissent les routes et les ruines de Lordaeron. Ses nécromanciens ajoutent de nouveaux soldats partout où l'on trouve des corps." }, { "La Scholomance et Stratholme sont de grands centres de cette besogne, tandis que les Souilles de Tranchebauge montrent jusqu'où porte son influence. Les morts n'ont besoin ni de récolte ni de repos, et le pays qu'ils occupent perd peu à peu la vie qui le faisait vivre." }, { "Parmi les os et les vêtements en lambeaux se trouvent les restes d'habitants ordinaires. L'armée n'a que faire de leurs anciens métiers, mais un carnet de terrain peut encore leur faire une place." } } },
    ["servants-of-the-firelord"] = { title = "Serviteurs du Seigneur du feu", note = { { "Les Attise-flammes du Cœur du Magma sont sans conteste des serviteurs de Ragnaros : des silhouettes armées au bas du corps serpentin, chez elles parmi les feux sous le mont Rochenoire. Lucifron, Gehennas, Shazzrah et leurs semblables gardent les approches du Seigneur du feu." }, { "Ici, la chaleur de la montagne fait partie d'un royaume habité. Ce qu'un nain tiendrait pour un endroit impossible où bâtir contient des gardes, des commandants et le siège d'un maître. L'absence de sol confortable est entièrement le problème du visiteur." } } },
    ["shadow-council"] = { title = "Le Conseil des ombres", note = { { "Le Conseil des ombres a aidé à lier l'ancienne Horde à la Légion. Son influence survit aujourd'hui dans des lieux comme Jaedenar, où cultistes et démons occupent le même sol corrompu." }, { "La Horde de Thrall a rejeté ces maîtres, mais les cercles d'invocation demeurent. Autour d'eux se rassemblent des adeptes de plus d'un peuple, poursuivant des arts dont le prix est déjà écrit à travers Gangrebois. Les arbres noircis accompagnent utilement toute promesse faite à l'intérieur du camp." } } },
    ["sharks-and-fish"] = { title = "Requins et poissons", note = { { "La surface d'un lac en dit très peu sur ses habitants. Le Loch Modan a ses furies. Les côtes ont des batteurs et des requins assez grands pour qu'on apprécie tout particulièrement la vue depuis un bateau." }, { "Ce sont les poissons qu'un pêcheur rencontre d'un peu trop près. Un aileron en eau libre n'est qu'un fragment de la créature qui se trouve dessous, et un banc peut changer un bassin tranquille en mouvement soudain. Le livre de la vie sous la surface est épais. Cette page en couvre les passages les plus dentus." } } },
    ["silithid"] = { title = "Silithides et Qiraji", note = { { "Les ruches silithides changent la forme des déserts du sud. Des monticules s'élèvent au-dessus de tunnels occupés par des guêpes, des ouvriers et de grands ravageurs cuirassés. La surface n'offre qu'une vue partielle de la population qui vit dessous." }, { "Les Qiraji d'Ahn'Qiraj commandent ces essaims. Il y a mille ans, la guerre des Sables changeants s'est achevée avec leurs armées scellées derrière le mur du Scarabée par les elfes de la nuit et les dragons." }, { "Les ruches au-delà de ce mur font de la vieille guerre une affaire actuelle. Un monticule bas à l'horizon peut signaler une revendication bien plus vaste sous le sable." } } },
    ["snakes"] = { title = "Serpents", note = { { "Un serpent peut occuper fort peu de l'attention d'un voyageur jusqu'au moment où il traverse le chemin. Enroulé, son corps ne dit presque rien de sa longueur, et une tête dressée suffit à faire d'un modeste bout de terrain une propriété bien gardée." }, { "Les serpents des Cavernes des lamentations ont été changés par le cauchemar qui y règne. À Zul'Gurub, les serpents ont leur place dans le culte du dieu du sang. Les deux lieux donnent au naturaliste davantage à méditer que les écailles et le venin, encore que ceux-ci restent des sujets tout à fait suffisants." } } },
    ["spiders"] = { title = "Araignées", note = { { "Les toiles partagent une grotte entre l'espace que le voyageur voit et l'espace déjà occupé. Dans les mines d'Elwynn et à Tissebois, sur Teldrassil, les araignées elles-mêmes sont souvent assez grosses pour expliquer pourquoi un chemin familier est devenu silencieux." }, { "Leurs glandes à venin et leur soie attirent l'attention des apothicaires et des artisans. La soie est un matériau particulièrement fin à trouver tendu en travers d'une porte abandonnée. Celle qui l'a tissée n'a besoin d'aucun métier à tisser, et ne s'intéresse en rien à l'usage qu'on fera de l'ouvrage terminé." } } },
    ["stags-and-steeds"] = { title = "Cerfs, coursiers et brouteurs", note = { { "Zhévras et girafes appartiennent aux larges horizons des Tarides, tandis que les cerfs d'Ashenvale apparaissent entre les troncs des vieux arbres. Leurs silhouettes différentes aident le voyageur à lire le pays avant qu'aucun panneau ne le fasse." }, { "Les chasseurs prisent leur viande et leur peau, mais Ogtinc, en Azshara, s'intéresse autrement aux coursiers Sabots-de-mousse. Il voit dans leurs bois intacts l'esprit d'un animal sûr de lui, et en demande une paire parfaite. Cette couronne impressionnante est aussi le moyen de défense du coursier, ce qui rend un spécimen intact difficile à obtenir." } } },
    ["syndicate"] = { title = "Le Syndicat", note = { { "Le Syndicat occupe les restes de la puissance d'Alterac : des villages en ruine dans les montagnes, des positions à Fort-de-Durn et un point d'appui à Stromgarde. Nobles dépossédés et criminels à gages font un remplaçant bien précaire pour un royaume." }, { "Leurs camps ont toujours des officiers et des ambitions, même quand leur travail se résume au vol. Un seigneur déchu peut garder son titre longtemps après avoir perdu les moyens d'en vivre. Dans les contreforts, le voyageur de passage peut être prié de combler la différence." } } },
    ["tallstriders"] = { title = "Hauts-trotteurs", note = { { "Les hauts-trotteurs sont des oiseaux des plaines, haut perchés sur leurs pattes et au long cou, et les trotteurs des plaines de Mulgore et des Tarides sont, après le kodo, le spectacle le plus familier des prairies. Ils sont assez inoffensifs tant qu'on ne les accule pas, après quoi ils frappent assez fort pour briser un bouclier." }, { "Les taurens les chassent pour leur viande et leurs plumes, avec les remerciements que la Terre-Mère leur demande. Les elfes de la nuit de Sombrivage et de Gangrebois connaissent un cousin forestier, le trotteur des forêts." }, { "Leurs œufs sont très recherchés. Leurs mères le savent." } } },
    ["thunder-lizards"] = { title = "Lézards-tonnerre", note = { { "Un lézard-tonnerre porte la surprise d'un orage dans un corps lourd à quatre pattes. Les Tête-tonnerre des Tarides et les grandes bêtes de Désolace peuvent passer pour de simples brouteurs jusqu'à ce que la foudre rende la distinction évidente." }, { "Leur masse impressionne assez sans cela. Les lézards-tempête des falaises des Serres-Rocheuses, plus petits, partagent cette inquiétante parenté avec le tonnerre. Un ciel clair au-dessus du col ne garantit pas une traversée tranquille." } } },
    ["troggs"] = { title = "Troggs", note = { { "Les troggs sont sortis des profondeurs pour gagner Dun Morogh, le Loch Modan et Gnomeregan. Leur force est assez évidente. Leur lien avec l'histoire naine a été une découverte bien moins bienvenue." }, { "Les archives d'Uldaman décrivent un façonnement plus ancien de la pierre en vie, suivi des terrestres dont descendent les nains. Ces archives font du trogg un sujet d'étude pour la Ligue autant qu'un ennemi sur le chantier de fouilles." }, { "Ainsi, une même fouille peut livrer l'histoire d'un ancêtre et un habitant très en colère. L'archéologie arrange rarement ses sujets de façon commode." } } },
    ["turtles"] = { title = "Tortues", note = { { "La carapace d'une tortue fait du reste de la créature un détail, jusqu'à ce que la tête sorte. Les Gueules d'acier habitent les lacs et les rivières. Les grandes tortues côtières de Tanaris et d'Azshara portent le même modèle robuste dans l'eau salée." }, { "Leur patience est facile à admirer depuis la berge. De près, le bec mérite une étude tout aussi attentive. Entre les deux se tient un animal remarquablement équipé pour occuper une étendue d'eau sans paraître se donner la moindre peine." } } },
    ["twilights-hammer"] = { title = "Le Marteau du crépuscule", note = { { "Le Marteau du crépuscule est passé de clan orc à culte aux fidèles de bien des peuples. Ses camps se rassemblent autour de puissances anciennes : dans les profondeurs de Brassenoire, près d'idoles obscures, et à travers le pays élémentaire de Silithus." }, { "Les écrits du culte attendent la fin du monde, et ses invocateurs travaillent à la hâter. Les robes et l'attirail savant peuvent donner aux camps une apparence d'étude. Les seigneurs élémentaires invoqués expliquent à quoi servent ces études." } } },
    ["venture-company"] = { title = "La KapitalRisk", note = { { "Les ouvrages de la KapitalRisk se voient souvent avant ses ouvriers : un flanc de colline mis à nu dans les Serres-Rocheuses, du pétrole dans les Tarides, une mine taillée dans les falaises de Mulgore. Déchiqueteurs, foreuses et gardes à gages suivent la concession." }, { "Les gobelins organisent une grande part du travail, même si la main-d'œuvre et les gros bras viennent de plusieurs peuples. Pour les villages voisins, la compagnie est moins une préoccupation lointaine qu'un trou qui s'agrandit ou une lisière qui recule. Ses comptes peuvent bien chiffrer le bois. La colline vide est plus difficile à estimer." } } },
    ["water-elementals"] = { title = "Élémentaires d'eau", note = { { "Un élémentaire d'eau donne à une source ou à un bassin un habitant mouvant fait de sa propre substance. La glace est la même substance, gelée, et ses élémentaires ont leur place ici aussi. Les élémentaires d'eau souillés d'Ashenvale portent la corruption de leur forêt dans cette forme familière." }, { "Au large d'Azshara, les Hydraxiens poursuivent un tout autre but : s'opposer à Ragnaros et à ses serviteurs. Les mages invoquent eux aussi des élémentaires d'eau. Une vague qui se dresse en un corps est un spectacle saisissant, mais il faut quelque chose du lieu et de son histoire pour expliquer ce qu'elle fait là." } } },
    ["wendigos"] = { title = "Wendigos", note = { { "Les wendigos de Dun Morogh habitent des grottes enneigées comme l'antre Gris, où leur fourrure blanche disparaît contre la neige. La taille de leurs mains passe moins facilement inaperçue." }, { "Leurs peaux et leurs crinières sont des sujets familiers des chasses locales. Pour un jeune nain, les collines au-delà d'un village peuvent sembler le prolongement de sa maison. Un wendigo à l'entrée d'une grotte donne à ces collines une tout autre échelle. Toute grande silhouette dans la neige n'est pas celle d'un autre montagnard." } } },
    ["wildkin"] = { title = "Séléniens et chouettards", note = { { "Ces créatures ont la masse d'un ours sous un visage et des plumes de chouette, une combinaison qui mérite un moment d'attention tranquille. Les elfes de la nuit les associent à Elune et les considèrent comme sacrées." }, { "Des séléniens vivent à Sombrivage, et des chouettards occupent les Hinterlands et le Berceau-de-l'Hiver. Leurs noms et leurs tempéraments varient, mais les grands yeux ronds restent caractéristiques. Une forêt qui en abrite un peut donner l'impression d'être observée d'une manière qui n'a pas grand-chose à voir avec l'embuscade d'un chasseur." } } },
    ["wind-serpents"] = { title = "Serpents des vents", note = { { "Les serpents des vents tracent de longues formes vives dans le ciel des Tarides et de Mille pointes. Des ailes emplumées portent un corps qui semble fait pour le sol, et la foudre fournit une raison de plus de se méfier des apparences." }, { "Certains trolls vénèrent les serpents ailés, et des spécimens plus sombres ont leur place parmi les fidèles d'Hakkar. Les créatures sauvages n'en restent pas moins remarquables. Contre une falaise nue, un serpent des vents peut fournir presque toute la couleur du paysage." } } },
    ["wolves"] = { title = "Loups", note = { { "Un hurlement peut faire paraître habitée une forêt entière. Les loups vivent des champs de neige de Dun Morogh aux futaies d'Elwynn, et leurs différents pelages appartiennent à ces lieux aussi naturellement que les arbres. Les worgs, plus grands, donnent à la silhouette familière une mâchoire plus lourde." }, { "Les orcs ont fait entrer les loups dans leur vie, comme compagnons et comme montures. Les jeunes chasseurs rencontrent les meutes sauvages sur un tout autre pied. La faim se voit particulièrement chez les loups affamés qui rôdent près des routes qui bordent les villages. La distance entre la nature sauvage et un village est parfois très courte." } } },
    ["worgen"] = { title = "Worgens", note = { { "Arugal a appelé les worgens à la forêt des Pins argentés pour combattre le Fléau, et il a perdu le contrôle de ce qu'il avait invoqué. Le donjon d'Ombrecroc est désormais leur place forte, tandis que Bois-du-Bûcher, tout près, porte une malédiction qui change ses habitants à la nuit tombée." }, { "Les Plaie-de-nuit du bois de la Pénombre relèvent d'un autre récit troublé, mêlé à la Faux d'Elune et à l'appel décrit par Velinde Starsong. Leur présence ne s'explique pas simplement en montrant du doigt la tour d'Arugal." }, { "Les deux lieux ont acquis la même terrible silhouette entre les arbres : une tête de loup au-dessus d'un corps dressé. Les histoires qui se cachent derrière doivent être suivies séparément." } } },
    ["worms-and-grubs"] = { title = "Vers et larves", note = { { "Une bonne part du travail du monde se fait sous sa surface. Les larves se déplacent dans la pourriture des Maleterres, tandis que des fouisseurs plus grands occupent le sable et la pierre. Ce qui a l'air d'un sol vide peut être plein de vie." }, { "Les vers des rochers des profondeurs portent la question à l'attention du prospecteur avec une force inhabituelle. Une créature parfaitement à son aise dans la terre est un voisin encombrant pour quiconque essaie d'y percer un tunnel. La roche, semble-t-il, n'était pas libre." } } },
    ["yetis"] = { title = "Yétis", note = { { "Les yétis occupent les grottes de montagne d'Alterac au Berceau-de-l'Hiver, avec une espèce hirsute sur les hauteurs de Feralas également. Leurs corps larges et leurs épais pelages donnent même à une vaste caverne l'allure d'un logement exigu." }, { "Leurs cornes ont attiré l'attention d'Umi Rumplesnicker, à Long-guet. Il lui en faut une paire parfaite pour le yéti mécanique qu'elle construit afin d'effrayer ses amis. Les yétis vivants tiennent malencontreusement à ces pièces." } } },
  },
  atlas = {
    [1411] = { { "Les ravines rouges de Durotar canalisent les routes entre ses villages. Tranchecolline se dresse à leur croisement, avec Orgrimmar au nord, le village de Sen'jin vers la côte sud et le passage vers les Tarides à l'ouest." }, { "La vallée des Épreuves se trouve à l'écart de la grand-route. Le donjon de Tiragarde occupe la côte est, tandis que les îles de l'Écho se voient au large depuis le pays darkspear sans être pour autant aux mains sûres des Darkspear." }, { "Devant Orgrimmar, les tours des zeppelins donnent à l'approche un second horizon au-dessus des parois du canyon. Le voyageur qui cherche ici à traverser la mer devrait lever les yeux." } },
    [1412] = { { "Des plaines vertes et des kodos qui paissent sous un grand ciel : le foyer des taurens. Thunder Bluff se dresse sur ses mesas au nord. Sabot-de-Sang s'étend au sud, et la route court entre les deux puis file à l'est vers les Tarides." }, { "Les plaines sont clémentes, pour l'essentiel. Les puits appartiennent aux taurens, et valent d'être gardés. Ce n'est pas le cas des gnolls du rocher des Crins-pâles, des harpies de la crête des Furies-des-vents ni de la mine de la KapitalRisk. Les nains du site de fouilles de Bael'Dun creusent là où les taurens préféreraient qu'ils s'abstiennent." }, { "Les Rochers rouges, à l'est, sont un lieu de repos pour les morts honorés des taurens. Marchez-y en silence." } },
    [1413] = { { "La Croisée donne aux Tarides un centre d'où les routes partent clairement : au nord vers Ashenvale, à l'est vers Ratchet, à l'ouest vers les Serres-Rocheuses, et au sud par le camp Taurajo vers la Grande élévation." }, { "Le pays découvert rend les repères lointains faciles à voir et faciles à sous-estimer. Des murs d'épines marquent le terrain des hurans. Camps de centaures et oasis éparses coupent les plaines. Un lieu visible à l'horizon peut encore demander une longue marche." }, { "Le port de Ratchet relie la côte est à Baie-du-Butin. À l'intérieur, la route est la ligne la plus fiable à travers un paysage qui offre de l'espace dans toutes les directions." } },
    [1416] = { { "La route qui quitte Hautebrande grimpe des contreforts verts jusqu'à la neige et aux restes du royaume d'Alterac. Strahnbrande est occupée par le Syndicat, tandis que des ogres tiennent une grande partie de la capitale en ruine. Une tour sur une crête est un repère utile, mais une piètre promesse d'abri." }, { client = "classic", "Au bord du lac Lordamere, le dôme violet de Dalaran se voit de loin au-dessus des basses terres. Les mages reconstruisent derrière. La route ne mène le voyageur qu'à l'extérieur de leur ouvrage." }, { client = "forever", "Dalaran se dresse au bord du lac Lordamere, où l'archimage Modera cherche de l'aide face à une crise à l'intérieur de la cité. Des lignes telluriques perturbées ont rendu ses créations destructrices. La cité a assez de gardes pour paraître en ordre depuis la route." }, { "Plus haut, des grottes de yétis et des champs de neige coupent les sentiers de montagne. Le lac donne un point fixe en contrebas. Parmi les crêtes, le prochain tournant est souvent caché." } },
    [1417] = { { "Le viaduc de Thandol porte la route des Paluns jusqu'à un pays de pentes vertes et de vieilles fortifications. Le mur de Thoradin marque le passage occidental vers Hautebrande. Les grands murs de Stromgarde se dressent au-dessus de la côte sud-ouest." }, { "Le Refuge de l'Ornière se trouve parmi les collines du centre pour l'Alliance, tandis que Trépas-d'Orgrim tient le nord-est pour la Horde. Stromgarde elle-même est partagée entre ses derniers défenseurs, les forces du Syndicat et les ogres. Un mur dessiné intact sur une carte n'enferme pas forcément un seul village sûr." }, { "Les cercles de pierres sont des repères bien visibles en terrain découvert. La crique de Faldir se cache sous les falaises du sud, bien moins visible depuis la route que depuis la mer." } },
    [1418] = { { "La descente depuis le Loch Modan laisse brusquement derrière elle le pays vert. Des crêtes rouges découpent les Terres ingrates en longues vallées sèches, avec les murs de Kargath à l'ouest et les fouilles autour d'Uldaman près de l'accès nord." }, { "La forteresse d'Angor est un terrain Sombrefer. Des camps d'ogres occupent les collines du sud, et des draconiens noirs tiennent le ravin de Lethlor, à l'est. L'étendue découverte la plus nette n'est pas forcément la route la plus tranquille." }, { "Les chantiers de la Ligue fournissent plusieurs repères utiles, même si une tente et un tas de déblais se ressemblent beaucoup vus de la crête suivante. Dans ce pays, la couleur de la pierre en dit moins à un arpenteur que sa forme." } },
    [1419] = { { "La route qui descend du marais des Chagrins atteint le Rempart-du-Néant au-dessus d'une étendue rouge. La forteresse surveille la Porte des ténèbres, dont le cadre encore debout se dresse plus au sud, dans le pays que l'invasion a balafré." }, { "Les ogres Cognepeur occupent les collines de l'ouest, et des démons tiennent la Balafre impure. Au-delà du donjon, le voyageur n'a guère de repères amicaux pour s'orienter. La Porte est assez facile à trouver. Trouver un endroit confortable près d'elle est une autre affaire." } },
    [1420] = { { "Les routes de Tirisfal relient le Glas, Brill et les ruines de la capitale de Lordaeron, puis filent à l'est vers la Barricade. Les vieilles fermes et les moulins donnent encore à la campagne des divisions reconnaissables, même si beaucoup de leurs habitants sont morts." }, { "Le Monastère écarlate occupe le nord-est, avec des postes de guet au-delà. Le lac Étincelant a des murlocs le long de ses rives, et les bois cachent leurs propres dangers." }, { "Brill est le principal village des Réprouvés au bord de la route. Près des ruines de la capitale, les tours des zeppelins relient ce pays tranquille à Orgrimmar et à Grom'gol, un croisement de routes étonnamment animé au-dessus des arbres." } },
    [1421] = { { "Les Pins argentés s'étendent entre Tirisfal et la frontière fermée de Gilnéas. Le Sépulcre domine la grand-route, qui continue vers le sud en passant par Bois-du-Bûcher et tourne vers Hautebrande." }, { "Le donjon d'Ombrecroc surplombe Bois-du-Bûcher, dont les rues de village familières deviennent un terrain worgen la nuit. Plus au sud, le mur de Grisetête barre la route de Gilnéas. C'est une frontière avec un royaume derrière, pas un col à travers les montagnes." }, { "Les mages de Moulin-de-l'Ambre occupent les bois de l'est. Entre leurs possessions, le donjon et les villages des Réprouvés, une courte traversée sur la carte passe par plusieurs revendications bien différentes sur la forêt." } },
    [1422] = { { "La route entre par la Barricade et traverse un pays agricole en ruine vers la Thondroril. Andorhal se dresse près du centre, ses rues et ses bâtiments brisés marquant encore l'ancienne ville du grain." }, { "Âtreval reste une place forte écarlate au nord. Au sud, Caer Darrow occupe une île du lac Darrowmere, avec la Scholomance dessous. Le camp du Noroît donne à l'Alliance un point d'appui tout proche." }, { "Les fermes sont faciles à reconnaître et difficiles à approcher. Leurs chaudrons de peste ont fait de chaque champ un terrain hostile à part entière, où une carte des routes doit servir un tout autre but que rentrer la moisson." } },
    [1423] = { { "La Thondroril marque l'accès occidental à un pays d'arbres morts et de fermes en ruine. Les routes atteignent Stratholme au nord-ouest et la chapelle de l'Espoir de Lumière à l'est, où l'Aube d'argent entretient un refuge." }, { "La Main de Tyr est une place forte écarlate au sud-est. Zul'Mashar occupe les hauteurs du nord. Au-dessus du Pestebois flotte Naxxramas. Peu de repères sont plus faciles à reconnaître, ou moins agréables à voir." }, { "Les bâtiments de Comté-de-Darrow marquent encore un village dans la plaine, même si ses habitants relèvent d'un récit plus troublé. Dans ce pays, une carte peut rester parfaitement exacte quand presque tout ce qu'elle décrit a été perdu." } },
    [1424] = { { "Hautebrande s'étend entre les pentes d'Alterac et la mer. Austrivage donne à l'Alliance un port et une ville sur la côte. Moulin-de-Tarren est le point d'appui des Réprouvés à l'intérieur des terres. Fermes et routes disputées occupent l'espace entre les deux." }, { "La route de l'est rejoint Arathi par le mur de Thoradin. D'autres chemins mènent à l'ouest vers les Pins argentés, au nord vers Alterac et vers les hauteurs des Hinterlands. Les murs en ruine de Fort-de-Durn se remarquent près des routes de l'est, même si le Syndicat tient désormais l'ancien donjon d'internement." }, { "Ce devrait être un pays simple à traverser : collines basses, champs cultivés et routes en abondance. La difficulté vient rarement du terrain." } },
    [1425] = { { "L'accès de l'ouest monte de Hautebrande jusqu'au Nid-de-l'Aigle, où les griffons des Wildhammer partagent les hauteurs au-dessus de la vallée. La route serpente ensuite vers l'est à travers des collines boisées et d'anciennes possessions trolles." }, { "Jintha'Alor s'élève en terrasses au sud-est, tandis que le grand arbre de Seradane marque un pays tenu par les dragons, au nord. Le village des Revantusk occupe la côte est et offre à la Horde son propre point d'appui au pied des collines." }, { "La hauteur du Nid-de-l'Aigle offre une belle première vue, mais une grande partie de la route disparaît sous les arbres avant d'atteindre la mer. Les Wildhammer ont choisi un excellent pays pour voyager à dos de griffon." } },
    [1426] = { { "De la neige, de la pierre et des nains, dans cet ordre. Les vallées courent d'est en ouest sous les pics qui cachent Forgefer, et l'unique route les suit : de la vallée des Frigères par le tunnel jusqu'à Kharanos, en montant jusqu'à la grande porte de la cité, puis vers l'est par le col jusqu'au Loch Modan." }, { "Kharanos a la distillerie Thunderbrew et le meilleur feu du pays. À l'ouest, le terrain appartient aux trolls Frostmane, et plus à l'ouest encore Gnomeregan se dresse derrière ses murs, empoisonnée. Les gnomes ne rentrent pas chez eux, et vous ne devriez pas y entrer sans une bonne raison et de meilleurs amis." }, { "Emportez un manteau de rechange et restez sur la route par tempête de neige. Les congères sont profondes, et les troggs des Frigères se moquent bien que vous soyez $gperdu:perdue;." } },
    [1427] = { { "Le Chaudron creuse une grande fosse au centre de la gorge des Vents brûlants, et les galeries Sombrefer s'étendent sous la surface. D'en haut, les échafaudages et les entrées de mine ne montrent qu'une partie du pays que le voyageur aura peut-être à traverser." }, { "La halte du Thorium est le point d'appui de la Confrérie du thorium, au nord. Le mont Rochenoire offre le passage vers le sud et les steppes Ardentes. Depuis les terres voisines, on atteint la gorge par des brèches plus étroites dans les montagnes." }, { "Terrils de scories et machines brisées font ici des repères utiles. C'est un paysage au travail, si ruiné qu'il paraisse depuis la crête suivante." } },
    [1428] = { { "Le mont Rochenoire domine l'horizon du nord, donnant à presque chaque route à travers les steppes le même grand repère. L'accès depuis les Carmines grimpe dans un pays couleur de cendre, où des crêtes brisées et de vieilles fortifications coupent la plaine." }, { "La Veille de Morgan occupe les hauteurs de l'est pour l'Alliance. La Corniche des flammes offre à la Horde un point d'appui plus au nord. Entre les deux s'étendent des camps Rochenoire, des draconiens et les restes de batailles plus anciennes." }, { "La montagne est aussi le passage vers la gorge des Vents brûlants. Du dehors, elle semble un mur plein au bout du pays. À l'intérieur, l'échelle de ses ponts et de ses salles devient le problème suivant du voyageur." } },
    [1429] = { { "La grand-route d'Elwynn part de Hurlevent, passe par Comté-de-l'Or et file à l'est vers les Carmines. Comté-du-Nord occupe une vallée abritée au nord, tandis que le passage de l'ouest mène à la Marche de l'Ouest. Fermes, ponts et lacs donnent à ce pays des repères d'une netteté inhabituelle." }, { "Les mines sont moins ordonnées que les champs au-dessus : des kobolds occupent Fargodeep et Veine-de-jaspe, et les Défias s'activent loin dans la forêt. Au sud-ouest, les camps des Rivepatte font des bois clairs autour de la rivière un terrain dangereux." }, { "Hurlevent n'est jamais loin en lieues. Un fermier qui attend de l'aide contre une mine ou un camp peut mesurer la distance autrement." } },
    [1430] = { { "La route du bois de la Pénombre au marais des Chagrins franchit le défilé de Deuillevent entre la roche nue et des à-pics profonds. Le chemin principal est assez court sur une carte, mais les arbres morts et les bâtiments vides donnent peu de raisons de s'attarder." }, { "Un embranchement au sud descend vers Karazhan et le village abandonné à ses pieds. La tour est scellée, ces temps-ci. Sa hauteur en fait un excellent repère au-dessus d'un pays où presque tout le reste semble avoir cessé de pousser." } },
    [1431] = { { "Les routes du bois de la Pénombre traversent une forêt qui laisse peu de jour arriver au sol. Sombre-Comté est le principal refuge à l'est, et les Veilleurs en tiennent les abords. Le défilé de Deuillevent s'étend au-delà. La route du sud descend vers Strangleronce." }, { "À l'ouest, la Colline-aux-Corbeaux et son cimetière occupent un pays bien moins sûr que ne le suggèrent les noms de fermes familiers de la carte. Le verger pourrissant et les maisons abandonnées conservent la forme d'une vallée habitée, sans grand-chose de son ancienne vie." }, { "Les routes relient toujours les lieux qu'elles devaient desservir. Cela en fait des repères utiles, même quand la destination est devenue un endroit que le voyageur préférerait éviter." } },
    [1432] = { { "Un long lac retenu par le barrage de Formepierre, le plus bel ouvrage de l'ingénierie naine hors de Forgefer, et je ne veux entendre aucune objection. Thelsamar se tient sur la rive ouest, sur la route qui vient de Dun Morogh, et la route continue au nord vers les Paluns et au sud vers les Terres ingrates." }, { "La vallée des Rois, au col, a des rois de pierre pour la garder. Le reste du pays a besoin d'être surveillé : des troggs dans la vallée des Brisepierre, des kobolds dans les mines, et des ogres au bastion des Mo'grosh dans les collines du nord-est." }, { "Les hauts-elfes du pavillon des Pérégrins restent entre eux et connaissent le pays mieux que n'importe quel nain. Demandez-leur conseil avant de partir chasser." } },
    [1433] = { { "Comté-du-Lac se tient sur la rive ouest du lac Placide, où ponts et routes réunissent les accès depuis Elwynn et le bois de la Pénombre. L'eau donne à la vallée un centre large et beau, et des repères d'une netteté inhabituelle." }, { "Les hauteurs de l'est sont une autre affaire. Le donjon de Guet-de-pierre est aux mains des Rochenoire, et des camps de gnolls occupent les crêtes entre les terres habitées et les montagnes." }, { "Depuis Comté-du-Lac, la rive d'en face paraît assez proche pour faire partie du pays de la ville. Les gardes la voient d'un œil beaucoup moins paisible." } },
    [1434] = { { "Strangleronce s'étend de la lisière sud du bois de la Pénombre jusqu'à Baie-du-Butin, à travers une longue bande de jungle. La route passe devant les expéditions du nord et le campement Grom'gol de la Horde avant d'atteindre le port gobelin, tout au bout." }, { "Ruines et camps occupés se trouvent juste derrière les arbres : la base de Kurzen, des villages trolls, le terrain des Mosh'Ogg et les abords de Zul'Gurub. Une clairière offre une vue sans offrir forcément une halte sûre." }, { "Baie-du-Butin est bâtie le long de la roche escarpée autour de son port, et le bateau pour Ratchet attend au pied des étages de la ville. Après tant de jungle, une route mesurée sur l'eau libre est un changement bienvenu." } },
    [1435] = { { "La route de l'ouest arrive du défilé de Deuillevent et traverse le marais vers Pierrêche, le principal village de la Horde. Un embranchement au sud rejoint les Terres foudroyées. Hors de la route, l'eau peu profonde coupe sans cesse ce qui semble être un sol ferme." }, { "Le bassin des Larmes recouvre le temple d'Atal'Hakkar. Le Sanctuaire des friches se trouve plus à l'est, tandis que le Havre boueux abrite des réfugiés draeneï au nord. Rejoindre la côte oblige à aller bien au-delà du dernier tronçon de route fiable." }, { "Le marais offre peu de hauteur d'où prendre un relèvement. Un temple englouti sous un lac est un repère particulièrement peu utile pour qui cherche le lac." } },
    [1436] = { { "La route de la Marche de l'Ouest passe d'Elwynn à des terres agricoles découvertes et continue jusqu'à la colline des Sentinelles. La Milice du peuple tient la tour, qui reste un repère utile au-dessus de champs dont les propriétaires ont souvent fui." }, { "Ruisselune se trouve plus au sud, avec les Mortemines dessous. Ailleurs, des camps défias et des golems des moissons hostiles occupent un pays encore découpé par les haies et les chemins de ferme." }, { "Le phare est un repère net depuis la côte ouest, même si des camps de murlocs en coupent l'approche. La vue porte loin dans la Marche de l'Ouest. Savoir ce qui attend dans le champ suivant est la partie difficile." } },
    [1437] = { { "Dun Algaz fait descendre la route du Loch Modan dans de vastes marais, où les grandes routes se séparent vers Port de Menethil à l'ouest et le viaduc de Thandol au nord. La route surélevée offre une ligne plus ferme à travers un pays morcelé par les eaux basses." }, { "Les navires de Menethil relient les Paluns à Auberdine et à Theramore. À l'intérieur des terres, des camps Dragonmaw occupent les collines, les Sombrefer tiennent Dun Modr, et des draconiens rouges gardent les abords de Grim Batol, à l'est." }, { client = "forever", "Au-delà de l'ancien chantier des excavations de Whelgar, la nouvelle fouille pénètre dans des galeries anciennes. Les reliques rapportées à Whelgar donnent à la Ligue de bonnes raisons de garder l'accès sur ses cartes." }, { "Hors de la route, les roseaux peuvent cacher le bord d'un chenal aussi bien qu'un crocilisque. Le chemin le plus court jusqu'à la prochaine butte peut contenir bien plus d'eau que la carte ne le laisse croire." } },
    [1438] = { { "Teldrassil porte toute une forêt habitée au-dessus de la mer. La route va de Sombrevallon à Darnassus en passant par Dolanaar, avec des embranchements vers des clairières et un pays de tertres qui peuvent sembler bien loin du bord d'une île." }, { "Tissebois et les possessions des Pin-tordu coupent les bois habités. Les bassins fournissent de fréquents repères, même si leurs rives encaissées ne révèlent pas grand-chose de la hauteur qu'il y a dessous." }, { "Le chemin de la descente passe par le portail de Darnassus jusqu'à Rut'theran, d'où les bateaux partent entre les racines. Mieux vaut garder cette route en tête : une côte ne sert pas à grand-chose au voyageur quand elle se trouve si loin sous la route." } },
    [1439] = { { "Sombrivage est un long voyage le long d'une côte étroite. Auberdine rassemble les routes et les navires en son milieu, avec des bateaux vers Rut'theran et, de l'autre côté de la mer, vers Port de Menethil. La route du sud mène en Ashenvale." }, { "Le rivage et les bois de l'intérieur offrent des itinéraires bien différents. Épaves et camps de murlocs coupent les plages. À l'intérieur s'étendent les ruines hantées d'Ameth'Aran et de Bashal'Aran, les camps des Noirbois et la tour d'Althalaxx." }, { "La mer est un guide fidèle quand les arbres cachent la route. C'est aussi la raison pour laquelle tant de navires brisés sont devenus des repères." } },
    [1440] = { { "La grand-route d'Ashenvale traverse des bois profonds jusqu'à Astranaar, puis file à l'est vers les camps Chanteguerre et Azshara. Des embranchements mènent au nord vers Sombrivage, à l'ouest par le passage de montagne vers les Serres-Rocheuses, et au sud vers le Rempart de Mor'shan." }, { "Les villages sont assez éloignés les uns des autres pour que la forêt se referme sur le voyageur entre deux. Sur la côte, la grève de Zoram s'ouvre sur des ruines tenues par les nagas. À l'intérieur des terres, les camps furbolgs et le sol démoniaque autour de la colline Gangrefeu font de plusieurs clairières engageantes de bien mauvaises haltes." }, { "Les ponts et le lac d'Astranaar offrent un point fixe bienvenu au milieu de tant de bois. Au-delà, la vue porte rarement assez loin pour montrer toute la route qui reste." } },
    [1441] = { { "La Grande élévation descend des Tarides dans un canyon encombré de piliers de pierre. Le poste de Librevent se dresse au sommet de l'un d'eux, qu'on atteint par ses propres élévateurs. En contrebas, la route se faufile entre les falaises vers les Salines." }, { "La cime de Noir-nuage est le terrain du Totem sinistre, tandis que centaures et harpies occupent d'autres canyons latéraux. Les piliers font de bons repères jusqu'à ce que le suivant les cache." }, { "Vers l'est, le pays s'ouvre brusquement sur les étendues de sel et la piste des Mirages. Machines gnomes et gobelines remplissent un pays assez vaste, enfin, pour que le voyageur voie loin sans lever les yeux." } },
    [1442] = { { "Les routes des Serres-Rocheuses montent par des vallées étroites, avec la retraite de Roche-Soleil au milieu de la chaîne et Malaka'jin près des accès du sud. Les elfes de la nuit tiennent le pic des Serres-Rocheuses, loin au nord." }, { "Les coupes de la KapitalRisk ont ouvert de grandes plaies dans la forêt. Plus à l'ouest, le Val calciné est un sol brûlé occupé par des harpies et d'autres dangers. Le sentier des Tisseuses offre dans son nom un avertissement plus littéral." }, { "Le passage de montagne vers Ashenvale et les routes qui descendent vers les Tarides et Désolace en font un lieu de traversées. La distance seule donne une piètre estimation d'un voyage à travers tant de détours et de montées." } },
    [1443] = { { "Désolace s'ouvre sous les Serres-Rocheuses en crêtes grises et en vastes terrains exposés. La combe de Nijel occupe les hauteurs du nord pour l'Alliance. Proie-de-l'Ombre s'étend en contrebas sur la côte ouest pour la Horde. La route du sud rejoint Feralas." }, { "Les territoires des centaures remplissent une grande partie de l'intérieur, avec le Cimetière des kodos au milieu. La forteresse de Hache-Tonnerre et le Convent de Mannoroc marquent un terrain hostile d'une autre sorte. Sur la côte, le pays descend vers des eaux tenues par les nagas." }, { "Les os rendent le cimetière visible de loin. Le front de mer de Proie-de-l'Ombre offre à l'œil quelque chose de plus doux où se poser : un village tourné vers la mer plutôt qu'un camp de plus dans la poussière." } },
    [1444] = { { "Feralas se referme autour de la route en troncs immenses et en sous-bois touffu. Le passage du nord descend de Désolace. Vers l'est, la route atteint le camp Mojache et continue vers Mille pointes." }, { "Le bastion de Feathermoon se dresse au large sur l'île de Sardor, qu'on rejoint en bateau depuis la côte ouest. À l'intérieur, Hache-tripes s'élève au-dessus de la forêt, des ogres occupant une grande partie de la cité en ruine. Le grand arbre du Bosquet du rêve marque un terrain tenu par les dragons, plus au nord." }, { "La voûte peut cacher une pente considérable jusqu'à ce que la route commence à la gravir. Un relevé de Feralas doit faire de la place à la hauteur autant qu'à la distance." } },
    [1445] = { { "La route des Tarides entre à Âprefange par les roseaux et les eaux basses, pour finir par atteindre la chaussée et le port de Theramore. Les navires pour Menethil partent de la cité insulaire. Mur-de-Fougères, un village de la Horde qui compte des ogres Cognepierre parmi ses habitants, se dresse dans le marais du nord-ouest." }, { "Le pays d'Onyxia s'étend au sud, dans la tourbière du Ver. Ailleurs, des chenaux et des berges basses morcellent un terrain qui paraît continu de loin. Un coude de la route fournit souvent un repère plus sûr que les arbres, qui ont la fâcheuse habitude de tous se ressembler." }, { "Depuis la maçonnerie de Theramore, la terre ferme semble toute proche. Après quelques détours dans le marais, c'est la cité qui semble avoir disparu derrière." } },
    [1446] = { { "La descente depuis Mille pointes atteint Gadgetzan près de l'extrémité nord de Tanaris. Ses murs et Port Gentepression, sur la côte est, sont des points fixes utiles dans un désert dont le sud est bien moins peuplé." }, { "Zul'Farrak se dresse au nord-ouest, les ogres Cognedune occupent l'intérieur, et la crique des Gréements abrite des pirates derrière les collines de l'est. Les Grottes du temps s'ouvrent parmi les montagnes plus au sud-est." }, { "La route de l'ouest finit par descendre dans Un'Goro. Depuis le rebord, le cratère vert ressemble à un tout autre pays, ce qui est une découverte singulièrement agréable après tant de sable." } },
    [1447] = { { "La route arrive d'Ashenvale au-dessus d'une côte de temples brisés et d'arbres rouge et or. La halte de Talrendis et Valormok offrent de petits points d'appui près de l'accès occidental. Plus à l'est, les collines tombent à pic vers la baie des Tempêtes." }, { "Les nagas occupent une grande partie du rivage, tandis que des camps de satyres et des expéditions elfes tiennent le terrain parmi les ruines. Azuregos parcourt le sud. Une ligne droite sur la carte peut cacher à la fois une falaise et le long détour qu'elle impose." }, { client = "classic", "La grande porte des collines du nord porte sur la carte le nom des Grumegueules, mais elle est fermée. Les tunnels furbolgs fréquentés qui mènent à Reflet-de-Lune et au Berceau-de-l'Hiver se trouvent à Gangrebois, bien à l'ouest d'ici." }, { client = "forever", "La grande porte de pierre des collines du nord mène au repaire des Noiregueules, foyer d'une tribu furbolg corrompue. Les tunnels des Grumegueules vers Reflet-de-Lune et le Berceau-de-l'Hiver restent bien à l'ouest d'ici, à Gangrebois." } },
    [1448] = { { "La route de Gangrebois monte au nord depuis Ashenvale à travers une forêt dont les arbres morts et malades laissent de longues trouées dans la voûte. Le Sanctuaire d'émeraude se trouve près de l'accès sud. Le poste de la Vénéneuse et la clairière de Griffebranche offrent des points d'appui distincts plus loin dans la vallée." }, { "Jaedenar et les camps des Jadefeu occupent une partie du sol le plus profondément corrompu. Au bout nord, les tunnels des Grumegueules mènent à Reflet-de-Lune et au Berceau-de-l'Hiver, pourvu que leurs gardes laissent passer." }, { "Un bassin vert n'apporte ici aucun réconfort à un paysage qui a l'air assoiffé. La couleur appartient au mal, et se voit souvent à travers les arbres avant le bassin lui-même." } },
    [1449] = { { "Le chemin qui descend de Tanaris révèle Un'Goro d'un seul coup : une jungle dense autour de la crête de la Fournaise, les fosses de goudron et les sources chaudes trouant le vert. Le refuge des Marshal s'adosse au rebord nord. La route vers Silithus remonte au nord-ouest." }, { "Le volcan central est un excellent repère et un terrain difficile. Loin de lui, la voûte cache des raptors, des diablosaures et le territoire silithide de la Balafre sinueuse. Le cratère est plus facile à embrasser d'en haut qu'à traverser d'en bas." }, { client = "classic", "Des cristaux brillants se trouvent dans tout le bassin, et les pylônes offrent un autre sujet aux recherches de l'expédition. La carte marque leurs positions. Les expliquer est un tout autre travail." }, { client = "forever", "La terrasse du Façonneur donne aux traces des Titans dans le cratère une place sur la carte, à côté des pylônes et des cristaux épars. Un nom pour un site ancien laisse une grande quantité de jungle inexpliquée." } },
    [1450] = { { "Le lac Elune'ara s'étend au centre de Reflet-de-Lune, avec Havrenuit sur sa rive et le sanctuaire du gardien Remulos tout près. Les druides arrivent par leur propre magie. Les autres voyageurs gagnent d'ordinaire la vallée par les tunnels des Grumegueules depuis Gangrebois." }, { "Le Cercle cénarien accueille ici les deux factions, et la fête lunaire amène des visiteurs de bien plus loin. Le calme est réel, même si la lutte autour du Rêve d'émeraude a atteint jusqu'à cette vallée." }, { "Pour un arpenteur, le lac est la constante bienvenue : un repère large et dégagé après le passage de montagne encaissé." } },
    [1451] = { { "Le chemin qui vient d'Un'Goro atteint Silithus au bord nord-est d'un vaste désert. Le fort Cénarien domine l'intérieur, offrant aux voyageurs un point fortifié d'où juger les distances entre les ruches." }, { "Le Marteau du crépuscule occupe des camps à travers l'étendue, tandis que le grand mur du Scarabée marque Ahn'Qiraj, au sud. Des monticules silithides coupent ce qui pourrait autrement passer pour du sable découvert." }, { "Le village de Sudevent reste un village reconnaissable sur la carte et une ruine sur le terrain. Les routes et les tours sont si rares qu'un seul bâtiment debout peut compter énormément pour s'orienter." } },
    [1452] = { { "Le passage des Grumegueules s'ouvre sur les vastes champs de neige du Berceau-de-l'Hiver, avec Long-guet qui rassemble le commerce près du centre. La ville des gobelins donne aux deux factions un toit et un croisement de routes parmi les montagnes." }, { "Pluie-d'Étoiles se trouve à l'ouest, les draconiens bleus de Mazthoril tiennent les grottes du sud, et le pays des yétis s'élève au-delà des collines des Chardons de glace. Des camps Tombe-hiver coupent d'autres accès à travers la neige." }, { "La gorge du Sombre murmure entaille l'extrême sud, où les démons font à la vallée une frontière lugubre. Les sources chaudes sont des repères plus aimables : de l'eau sombre et libre et de la vapeur qui monte sur beaucoup de blanc." } },
    [1453] = { { "La porte de Hurlevent fait passer la route d'Elwynn devant les statues de la vallée des Héros et l'amène dans le quartier commerçant. Des canaux séparent les quartiers, et les ponts font une bonne part du travail qu'une large avenue ferait dans une autre cité." }, { "Les griffons partent du quartier commerçant, et le tram des profondeurs relie le quartier des Nains à Forgefer. La cathédrale est un repère facile au-dessus des toits. La Prison, au bord de l'eau, en est un moins rassurant." }, { "La pierre blanche de la cité reste une réponse impressionnante à sa ruine passée. La traverser efficacement demande un peu plus d'attention aux ponts qu'à la silhouette des toits." } },
    [1454] = { { "Orgrimmar suit les plis d'un canyon de roche rouge, sa grande porte s'ouvrant au sud sur Durotar. Rampes et passages relient les vallées à l'intérieur. Deux destinations proches sur une carte plate peuvent demander une longue montée de l'une à l'autre." }, { "Le fort Grommash se dresse dans la vallée de la Sagesse, tandis que les cavaliers célestes de la cité partent d'une haute tour. Hors des murs, des zeppelins relient la capitale à Fossoyeuse et à Grom'gol." }, { "Le canyon fait partie de la forteresse autant que les murs bâtis. Sa forme se comprend le mieux d'en haut, ce qui tombe bien une fois que le voyageur a trouvé les cavaliers célestes." } },
    [1455] = { { "La porte de Forgefer s'ouvre sur la neige et donne sur une cité disposée autour de la Grande forge. L'anneau principal relie les Communs, le Haut-Siège, Brikabrok et le hall des Explorateurs. Savoir dans quel sens en faire le tour épargne bien des pas." }, { "Le tram des profondeurs part de Brikabrok pour Hurlevent, et les griffons s'envolent à côté de la Grande forge. Le hall de la Ligue offre une destination plus calme, même si ses collections suscitent parfois autant de disputes que l'hôtel des ventes." }, { client = "forever", "Sous la cité, les cavernes du Vieux Forgefer mènent à la salle des Thanes. Des intrus Sombrefer ont trouvé un chemin jusqu'à ses chambres fortes inférieures. La cité s'est découvert une nouvelle frontière juste sous les pieds du roi." } },
    [1456] = { { "La cité des taurens, sur les mesas du nord de Mulgore, reliées par des ponts de corde et qu'on atteint par de grands élévateurs depuis la plaine." }, { "Chaque cime a sa fonction : la cime des Anciens pour les anciens et les druides, la cime des Esprits pour les chamans et les prêtres, la cime des Chasseurs pour les chasseurs et les guerriers. La banque et l'hôtel des ventes sont sur la cime centrale, et les cavaliers célestes s'envolent de la tour." }, { "Les ponts se balancent. Ne regardez pas en bas, et ne courez pas." } },
    [1457] = { { "Darnassus s'ouvre autour de l'eau et de larges ponts, haut dans Teldrassil. Le temple de la Lune donne à la partie sud de la cité son grand repère, tandis que marchands et artisans occupent les terrasses plus au nord." }, { "La route de l'est mène à Dolanaar. Du côté ouest de la cité, le portail permet de descendre jusqu'à Rut'theran et aux bateaux en contrebas. Un arpenteur habitué à mesurer la hauteur d'une cité depuis le sol a ici quelques réglages à faire." } },
    [1458] = { { "Fossoyeuse s'étend sous la capitale en ruine de Lordaeron, et l'on y descend par des élévateurs sous l'ancienne salle du trône ou par l'accès extérieur des égouts. À l'intérieur, des passages circulaires et des canaux verts relient les quartiers." }, { "La banque centrale est un repère utile. Le quartier royal et le travail des apothicaires se trouvent plus avant dans la cité. Pour y arriver, il faut faire attention aux niveaux autant qu'aux tournants." }, { "En surface, les tours des zeppelins se dressent hors des ruines. Un voyageur arrivé par les airs peut n'avoir que quelques pas à faire jusqu'à la cité et passer pourtant un bon moment à trouver le bon chemin pour descendre." } },
    [2521] = { { "Zéphras est une île habitée suspendue dans le Mur-Céleste. Valanaar occupe le bord sud-est, avec le siège du grand ancien et les quais aériens. Ban'aethal, au nord, a été évacuée à mesure que les pylônes qui portent l'île défaillent." }, { "Les fermes du sud cèdent la place aux hautes-terres de Shen'dar, puis à des villages, des sanctuaires et à la forêt de Trombenoire. Sur un sol ordinaire, une route coupée est un désagrément. Ici, c'est le sol lui-même qui fait partie des incertitudes du relevé." }, { "Des fend-ciel quittent Valanaar pour Dalaran et Mulgore. Les routes vers Anvilas et Siroccas se sont tues, laissant ces autres îles hors des relèvements actuels du voyageur." } },
  },
  herbs = {
    [13463] = { { "La Feuillerêve se cueille parmi les ruines d'Azshara et dans Hache-tripes, ainsi que dans les terres balafrées autour de Rochenoire." }, { "Les potions de protection supérieures l'emploient contre le feu, le givre, la nature, l'ombre et les arcanes. Le Flacon de sagesse distillée en a besoin aussi." } },
    [13464] = { { "Le Sansam doré se cueille à Un'Goro et en Azshara, et dans des pays abîmés comme Gangrebois et les Maleterres de l'est." }, { "Les breuvages majeurs de soins et de régénération l'emploient. Les remèdes rapportés de ces lieux ne manquent pas de travail qui les attend." } },
    [13465] = { { "La Sauge-argent des montagnes se cueille au Berceau-de-l'Hiver et à Un'Goro, malgré la vue bien différente qu'on a depuis le fond du cratère." }, { "Elle entre dans la Potion de soins majeure, et fait avec la Fleur de peste l'Elixir de la Mangouste." } },
    [13466] = { { "La Fleur de peste se cueille dans les deux Maleterres, où trouver une pousse utile au milieu des champs ruinés est un petit soulagement." }, { "La Potion de purification et l'Elixir magesang l'emploient tous deux. La Sauge-argent des montagnes l'accompagne dans l'Elixir de la Mangouste. Une plante cueillie dans ce pays dévasté peut encore servir les vivants." } },
    [13467] = { { "Le Calot de glace appartient aux tournées de cueillette du Berceau-de-l'Hiver. La neige offre à l'herboriste un paysage d'une constance inhabituelle pour apprendre où il pousse." }, { "La Potion de mana majeure et la Potion de purification l'emploient, tout comme le Flacon de sagesse distillée." } },
    [13468] = { { "Le Lotus noir est une trouvaille rare dans un petit nombre de terres dangereuses. Le cueilleur qui en repère un a toutes les raisons de se souvenir de l'endroit." }, { "Les grands flacons le réclament, dont ceux des Titans et du pouvoir suprême. Bien des bouquets se renouvellent au fil d'une tournée ordinaire. Celui-ci décide plutôt du moment où le travail le plus ambitieux peut commencer." } },
    [2447] = { { "Le Pacifique est une fleur familière le long des premières routes qui partent de chez soi, et utile longtemps après qu'un herboriste a appris des noms plus rares." }, { "Avec la Feuillargent, il donne une Potion de soins mineure. Il y a quelque chose d'agréable à trouver les débuts d'un remède dans un pays où un apprenti sait encore reconnaître le chemin du retour." } },
    [2449] = { { "La Terrestrine pousse dans toutes les terres habitées, et jusque dans les Cavernes des lamentations. C'est l'une des premières racines qu'un herboriste apprend à reconnaître." }, { "L'Élixir de Force mineure et l'Elixir de Robustesse mineure commencent tous deux par elle. Des noms si imposants ont des ingrédients modestes, ce qui console un apprenti." } },
    [2450] = { { "L'Églantine est familière dans les Tarides et dans les pays boisés de l'autre côté de la mer. Du Chardonnier peut venir avec les tiges cueillies." }, { "Les breuvages de soins et la Potion de Rage la réclament tous deux. Le même bouquet peut donc aider quelqu'un à se remettre d'un combat ou à se préparer à en commencer un autre." } },
    [2452] = { { "Le Chardonnier vient avec le Mage royal et l'Églantine plutôt que d'un carré à lui. L'herboriste qui le cherche doit faire attention à ce que donne le reste de sa cueillette." }, { "Les voleurs en font du Thé de chardon, tandis que les alchimistes l'emploient pour des breuvages de rapidité et de nage." } },
    [2453] = { { "La Doulourante est assez répandue pour devenir une étape régulière de la tournée de cueillette. Les Cavernes des lamentations et les profondeurs de Brassenoire en ont aussi, pour ceux que leurs affaires mènent sous terre." }, { "La Potion de soins et la Potion de purification du poison lui donnent un travail sûr." } },
    [3355] = { { "L'Aciérite sauvage est un nom familier aux herboristes qui parcourent les collines d'Arathi et le pays rocheux des Serres-Rocheuses." }, { "L'Élixir de défense inférieure et l'Élixir de robustesse inférieure l'emploient tous deux. L'armure est l'affaire du forgeron, mais l'alchimiste a quelques contributions à faire avant que le voyageur ne la boucle." } },
    [3356] = { { "Le Sang-royal pousse sur une vaste étendue de pays, des collines boisées à l'intérieur sec de Kalimdor. Sa valeur ne tient pas à une recherche difficile." }, { "Les breuvages de soins supérieurs et les potions de mana l'emploient tous deux, et les travailleurs du cuir en ont besoin pour les Gants d'herboriste. Une herbe de cueillette qui aide à faire des gants de cueillette tient une place plaisante dans le métier." } },
    [3357] = { { "La Vietérule se trouve dans les pays humides des deux continents, les marais et les terres de rivière offrant une grande part de la cueillette." }, { "La Potion de soins supérieure et le Breuvage de marche sur l'eau la réclament." } },
    [3358] = { { "La Moustache de Khadgar porte un nom dont le voyageur se souvient sans doute avant même d'apprendre où la chercher. L'herbe pousse dans plusieurs des terres boisées et marécageuses." }, { "La Potion de mana supérieure et l'Elixir d'Intelligence supérieure l'emploient, tout comme l'Huile glaciale. Le nom de l'archimage a trouvé son chemin jusqu'à une étagère très occupée." } },
    [3369] = { { "La Tombeline se cueille en des lieux où l'herboriste a peu de chances de se sentir tout à fait seul : le bois de la Pénombre, Désolace et le lieu de sépulture des Souilles de Tranchebauge, entre autres." }, { "L'Huile des ténèbres et la Potion de protection contre l'Ombre la réclament. Ces usages conviennent bien aux affaires qui amènent un cueilleur parmi les tombes." } },
    [3818] = { { "La Pâlerette se cueille à travers les terres du milieu, avec des carrés à l'intérieur du Monastère écarlate et du Kraal de Tranchebauge aussi." }, { "Les voleurs en préparent la Poudre aveuglante. Les alchimistes la mettent dans des potions pour devenir invisible et pour détecter l'invisible : la même herbe contribue aux deux camps d'une rencontre difficile." } },
    [3819] = { { "L'Hivernale offre à l'herboriste un voyage bien particulier : dans la neige des montagnes d'Alterac. Une plante familière est une compagnie bienvenue dans un pays où l'on perd facilement les sentiers." }, { "L'Huile glaciale, la Potion de protection contre le Givre et l'Elixir de Puissance du givre la réclament tous. L'herbe de montagne a du travail des deux côtés de la lutte contre le froid." } },
    [3820] = { { "L'Étouffante éloigne l'herboriste du chemin et l'emmène dans l'eau côtière. La cueillette elle-même plaide fort pour savoir ce qui pousse sous la surface." }, { "Le Breuvage de respiration aquatique est l'un de ses usages, avec les breuvages de mana et la Potion de libre action. La plante fournit le remède à un désagrément rencontré en la cueillant." } },
    [3821] = { { "La Dorépine gagne sa place dans une sacoche de travail par la variété de ses usages. Son pays de cueillette comprend les collines d'Arathi et les forêts de Feralas." }, { "Les breuvages de mana supérieurs, les élixirs d'agilité et la Potion de protection contre le Givre la réclament tous." } },
    [4625] = { { "La Fleur de feu appartient aux tournées de cueillette de Tanaris, des Terres ingrates et de la gorge des Vents brûlants. Aucun de ces pays n'est un endroit tranquille où s'arrêter pour remplir une sacoche." }, { "Le Carburant de fusée des gobelins et l'Huile d'immolation donnent une assez bonne idée de ses usages. La Pierre philosophale la réclame aussi, pour les alchimistes qui nourrissent une autre ambition pour le même bouquet." } },
    [765] = { { "La Feuillargent a sa place dans la même sacoche de cueillette que le Pacifique. Une plante n'a pas besoin d'être rare pour devenir indispensable à l'établi." }, { "Les breuvages mineurs de soins et de mana la réclament tous deux. Ces deux usages expliquent qu'un alchimiste qui en a cueilli en abondance découvre, assez vite, que l'abondance ne suffisait pas." } },
    [785] = { { "Le Mage royal est une trouvaille utile le long des routes au-delà des premiers villages. On cueille parfois du Chardonnier avec lui, ce qui donne à une seule halte une seconde récompense." }, { "Les alchimistes emploient le Mage royal dans les breuvages de mana et l'Elixir de Sagesse. Le nom place la barre haut. Le service qu'il rend à un jeune lanceur de sorts suffit amplement." } },
    [8153] = { { "La Sauvageonne se cueille avec le Lotus pourpre, une trouvaille de plus dans un pays qui vaut déjà d'être fouillé pour la fleur." }, { "Les travailleurs du cuir en ont besoin pour le cuir sauvage, et les tailleurs pour le tisse-rêve. La fleur et sa compagne trouvent du travail sur des établis bien différents." } },
    [8831] = { { "Le Lotus pourpre pousse dans des terres éparses des deux continents, et donne parfois de la Sauvageonne avec la cueillette." }, { "La Potion de sommeil sans rêve et le Breuvage de vision de rêve l'emploient tous deux. Un alchimiste peut offrir une nuit sans rêves ou un voyage à travers l'un d'eux, selon ce qui accompagne le lotus dans la fiole." } },
    [8836] = { { "Les Larmes d'Arthas poussent dans les Maleterres et à Gangrebois, et se trouvent dans les Souilles de Tranchebauge. C'est un nom bien sombre à apprendre parmi tant de champs ruinés." }, { "Le Breuvage de détection des morts-vivants et le Don d'Arthas en sont les deux préparations familières. Ni l'un ni l'autre n'allège beaucoup ce qu'évoque un bouquet rapporté de ce pays." } },
    [8838] = { { "La Soleillette reste une trouvaille bienvenue dans un pays aussi troublé que Gangrebois et les Maleterres, comme dans des terres plus vertes plus au sud." }, { "Les breuvages de soins et de mana excellents l'emploient tous deux." } },
    [8839] = { { "L'Aveuglette mène le cueilleur à travers le marais des Chagrins et Un'Goro, avec une autre réserve sous terre, à Maraudon." }, { "La Potion de mana excellente et l'Elixir des arcanes la réclament. Dans le Don d'Arthas, elle accompagne les Larmes d'Arthas." } },
    [8845] = { { "Les Champignons fantômes font d'un pays de grottes un endroit qui vaut d'être fouillé avec soin. Les Hinterlands et Désolace en ont, et l'on en trouve davantage à l'intérieur de Maraudon et de Hache-tripes." }, { "Les alchimistes s'en servent pour l'invisibilité et la puissance de l'ombre, mais en font aussi de la Teinture fantôme pour les tailleurs. Un champignon sorti du noir peut finir son voyage en couleur d'un vêtement." } },
    [8846] = { { "Le Gromsang se trouve sur le sol souillé de Gangrebois, près de la Porte des ténèbres et dans Hache-tripes. La tournée de cueillette passe par certaines des marques les plus tenaces que la Légion a laissées sur le monde." }, { "Le Flacon des Titans et l'Elixir de Force de brute le réclament tous deux. La Potion de tueur de démons aussi, un usage particulièrement satisfaisant pour une herbe cueillie en pareille compagnie." } },
  },
  fish = {
    [12238] = { { "Le Mérou de Sombrivage se cherche dans les rivières et les chutes à l'intérieur des terres, en retrait de la côte." }, { "Gubber Blump, à Auberdine, en demande une pêche et offre une canne à pêche pour la peine. Le poisson peut aider à équiper un pêcheur pour ce qui sortira de la rivière suivante." } },
    [13422] = { { "Les Anguilles pierre-écaille sont une prise précieuse au large d'Azshara et de Tanaris, surtout là où un banc se rassemble." }, { "L'Huile de pierre-écaille entre dans la Potion de Bouclier de pierre supérieure et dans de puissants flacons. Un tranquille moment de pêche peut finir en provisions destinées à un combat très bruyant." } },
    [13754] = { { "Le Barracuda luisant se pêche au large de Tanaris et d'Azshara, dans des eaux qui récompensent le pêcheur expérimenté." }, { "Le Barracuda luisant cuit rend de la santé et ajoute de l'endurance. Un poisson plus petit peut apporter à peu près le même encouragement avant une bataille que la grosse prise qu'on prépare en steaks." } },
    [13755] = { { "Le Calmar hivernal remplace la Perche estivale dans la pêche côtière de saison. Un coin de pêche familier vaut qu'on y revienne quand l'année tourne." }, { "Le Calmar grillé aiguise l'agilité. Les cuisiniers qui l'apprécient ont un intérêt pratique à suivre les saisons, indépendamment du temps qu'il fait." } },
    [13756] = { { "La Perche estivale est une prise saisonnière des côtes du sud. Un pêcheur qui retourne à un coin de pêche d'hiver peut y trouver un autre souper." }, { "La Perche fumée lui donne sa place au coin du feu. Le changement de saison peut atteindre la marmite même quand l'expédition est restée au même camp." } },
    [13757] = { { "L'Anguille électrique apparaît dans les eaux intérieures plus sauvages, avec des prises comme le Lutjan nagenuit et le Rouget." }, { "Elle n'a aucune place familière dans les préparations du cuisinier ou de l'alchimiste. Un carnet de terrain peut quand même faire de la place à un poisson sans d'abord lui trouver un usage." } },
    [13758] = { { "Le Rouget tient compagnie au pêcheur d'eau douce de jour comme de nuit, dans bien des eaux où l'heure décide des autres prises." }, { "Le Filet de rouget fournit un repas sûr. Les spécimens lourds sont pesés à part, et ont tendance à recevoir bien plus d'attention avant que quiconque n'aille chercher le couteau." } },
    [13759] = { { "Le Lutjan nagenuit fait de l'heure un critère dans le choix d'un coin de pêche. Il mord la nuit et aux lisières du jour, les premières heures après minuit étant particulièrement favorables." }, { "La Soupe de lutjan nagenuit aide un lanceur de sorts à retrouver son mana. Un pêcheur patient peut donner à ses compagnons une bonne raison de se féliciter du temps passé au bord de l'eau sombre." } },
    [13760] = { { "Le Saumon solécaille préfère la lumière du jour, dans des eaux également connues pour le Lutjan nagenuit. Un après-midi qui déçoit le pêcheur de nuit peut fort bien convenir à cette prise." }, { "Le Saumon solécaille poché aide la santé à revenir régulièrement. Les deux prises font travailler le même bout d'eau pour des appétits différents à des heures différentes." } },
    [13876] = { { "Ces jaune-queues pèsent de quarante à soixante-huit livres et viennent des côtes de Tanaris et d'Azshara." }, { "Pour une fois, le poids seul fait l'essentiel du travail de description d'une prise. La part du pêcheur dans le récit, c'est de l'avoir sorti de la mer." } },
    [13885] = { { "Les rougets lourds vont de trente-quatre à cinquante-deux livres, dans les mêmes eaux de haute contrée que la prise ordinaire." }, { "Le carnet devient ici particulièrement utile. Un poids précis est une petite défense contre le soupçon raisonnable que l'histoire a grandi sur le chemin du retour." } },
    [13888] = { { "La baie des Tempêtes, en Azshara, est le lieu de pêche du Homard Pince-noire. Le nom de ces eaux donne une assez juste idée du pays qui entoure le rivage choisi par le pêcheur." }, { "Le Ragoût de homard récompense le voyage par un repas consistant. Les homards pesés à part donnent à ces mêmes eaux une autre raison de rester dans la mémoire d'un pêcheur." } },
    [13889] = { { "Le Saumon Blanchécaille se pêche dans des eaux difficiles, dont celles du Berceau-de-l'Hiver et des terres qui entourent les grandes places fortes de la peste." }, { "Le Pain de saumon fait un beau repas de la prise ordinaire. Les spécimens plus lourds sont pesés à part." } },
    [13890] = { { "Le Poisson cuirassé est un trophée moins familier, tiré des eaux qui donnent aussi le Saumon Blanchécaille." }, { "Le cuisinier n'a pas de préparation habituelle pour lui. Sa place dans la pêche vaut tout de même d'être consignée. Un panier de pêche contient plus que les ingrédients d'une liste de courses." } },
    [13893] = { { "Le Grand barracuda vient de la baie des Tempêtes, où les pêcheurs expérimentés cherchent aussi le Homard Pince-noire." }, { "Le Steak de barracuda donne un repas copieux qui ajoute de l'endurance. Les géants pesés à part dans les mêmes eaux sont un autre trophée, de ceux qui peuvent rendre invraisemblable le récit d'un pêcheur même quand il est exact." } },
    [13901] = { { "Les saumons pesés à part vont de quinze à vingt-neuf livres et accompagnent le Saumon Blanchécaille dans la pêche." }, { "Ils donnent à une expédition de pêche familière un résultat bien à elle : ce poisson-là, à ce poids-là, de ce bout d'eau-là." } },
    [13907] = { { "Les homards pesés, de sept à vingt-deux livres, viennent de la baie des Tempêtes, en Azshara." }, { "Une prise du haut de cette fourchette mérite une entrée soignée dans le journal. \"Un homard\" est une description bien modeste de ce qui est sorti de l'eau." } },
    [13914] = { { "Les plus grands barracudas pesés vont de soixante-dix à cent trois livres, dans la baie des Tempêtes, en Azshara." }, { "Même sans les ajouts d'un pêcheur, une prise qui approche les cent livres explique bien assez un retour tardif." } },
    [1467] = { { "Le Poisson-lune se cherche dans le lac Placide, à Comté-du-Lac." }, { "Le chef des docks Baren en achète une pêche de dix. Une ligne lancée dans les eaux de la ville peut rapporter un peu d'argent en plus d'un moment tranquille au bord du lac." } },
    [16967] = { { "L'Ahi de Feralas envoie le pêcheur à la Verdantis, bien loin du coin d'Âprefange où pêche Nat Pagle." }, { "C'est l'une des quatre prises qu'il demande avant de transmettre son meilleur enseignement. Un voyage à travers Feralas est une part considérable de cette leçon." } },
    [16968] = { { "Le Frappeur Sar'theris emmène l'élève de Nat Pagle sur la côte de Désolace." }, { "C'est l'une des quatre prises de son épreuve. Le rivage change de l'intérieur gris, même si le voyage reste considérable pour un seul poisson." } },
    [16969] = { { "Le Sailfin bleu de la Côte sauvage est la prise que Nat Pagle exige de Strangleronce." }, { "Pour l'élève qui a déjà visité ses autres lieux de pêche, le nom annonce un long voyage de plus. La leçon s'étend bien au-delà du petit bout d'eau où le maître attend." } },
    [16970] = { { "Le Mahi Mahi de Brumejonc se cherche au large du marais des Chagrins, sur la grève qui lui donne une partie de son nom." }, { "Nat Pagle le compte parmi ses quatre prises d'épreuve. Rejoindre la mer à travers ce marais donne à la course un début difficile, avant même que la ligne ne soit lancée." } },
    [4603] = { { "Le Jaune-queue tacheté partage une grande part des lieux de pêche côtiers de la Morue rochécaille." }, { "Il a sa propre place dans le répertoire du cuisinier, même quand les deux arrivent dans le même panier de pêche. La mer n'a pas besoin de fournir une prise rare pour fournir un peu de variété." } },
    [6289] = { { "Le Lutjan à longue mâchoire est commun dans les rivières et les lacs du pays natal, et suit les pêcheurs bien au-delà de leurs premières leçons." }, { "La prise ordinaire se cuisine facilement. Le spécimen lourd qu'on attrape de temps à autre tend à trouver un autre usage : servir de preuve dans le récit de pêche du soir." } },
    [6291] = { { "Le Goujon brillant remplit le premier panier de pêche d'un apprenti dans des eaux familières, parfois à portée de vue d'une rue de la cité." }, { "Il donne un repas simple et utile. Une prise modeste est une compagnie bien suffisante pour un après-midi tranquille, surtout quand le cuisinier apprend lui aussi." } },
    [6292] = { { "Des lutjans de dix, douze et quinze livres se pêchent aux côtés du Lutjan à longue mâchoire." }, { "Les eaux familières du pays natal ont encore de la place pour une surprise. Un pêcheur n'a pas besoin d'atteindre une côte lointaine pour rapporter quelque chose qui vaille d'être pesé." } },
    [6303] = { { "Le Maquereau ombré est une prise familière des débuts le long de la côte. Il offre au pêcheur en mer un commencement sûr, là où le pêcheur des terres a ses goujons." }, { "Le plat cuisiné tout simple garde le même nom." } },
    [6308] = { { "Le Poisson-chat moustachu accompagne le pêcheur d'eau douce sur une vaste étendue de pays, y compris dans des eaux enfouies au fond de lieux fort peu accueillants." }, { "La plupart finissent au souper. Un gros poisson-chat pesé à part, en livres, risque de rester un sujet de conversation bien plus longtemps." } },
    [6309] = { { "Les gros poissons-chats se pèsent un par un, de dix-sept livres jusqu'à la rare prise de trente-deux livres." }, { "Ils partagent les eaux du Poisson-chat moustachu. Un coin de pêche ordinaire peut ajouter quelque chose d'extraordinaire au récit d'une soirée." } },
    [6317] = { { "La Furie du loch appartient au grand lac du Loch Modan, dont le barrage de Formepierre retient les eaux au-dessus des Paluns." }, { "Le Délice de furie du loch fait d'une prise locale un souper local. Il existe d'agréables façons pour un voyageur d'apprendre le nom d'un lieu." } },
    [6358] = { { "Le Bouche-noire huileux donne au pêcheur du travail pour l'alchimiste autant que pour le cuisinier. Ses bancs sont une vue prometteuse le long de la côte où l'on récolte." }, { "L'Huile de bouche-noire entre dans les breuvages de nage et le Breuvage de respiration aquatique. La prise peut aider un autre voyageur à rester un peu plus longtemps dans l'eau d'où elle vient." } },
    [6359] = { { "Le Lutjan de nagefeu se recherche pour son huile plutôt que pour le repas du soir. Ses bancs et les nappes huileuses de la côte méritent l'attention du pêcheur." }, { "L'Huile de feu sert à la fois la Potion de protection contre le Feu et l'Élixir de puissance du feu. L'alchimiste décide si la prise aidera quelqu'un à résister à la flamme ou à la manier." } },
    [6361] = { { "Le Thon arc-en-ciel vient des eaux côtières des deux continents. C'est l'une des prises qui obligent le pêcheur à apprendre un rivage autant qu'une route." }, { "Les cuisiniers le préparent sous son propre nom." } },
    [6362] = { { "La Morue rochécaille vient des eaux côtières plus loin dans les voyages d'un pêcheur, Strangleronce et Tanaris comptant parmi ses lieux de pêche." }, { "Le poisson cuisiné fournit un souper sans façon." } },
    [6522] = { { "Le Poisson déviant habite les oasis des Tarides et les Cavernes des lamentations en dessous, des eaux mêlées au rêve troublé de Naralex." }, { "Cru, ses effets sont imprévisibles. Le Délice de déviant peut déguiser le convive en pirate ou en ninja, tandis que les alchimistes emploient le poisson dans un Elixir de Taille de géant. C'est une prise qu'il vaut mieux identifier avant le souper." } },
    [6717] = { { "Les rouages électriques sont des outils perdus, pas des poissons : Wizbang Cranktoggle en a fait tomber une caisse par-dessus bord pendant son voyage vers Auberdine." }, { "Il lui en faut huit pour régler ses mécanismes. Une ligne lancée dans la mer peut fournir les débuts d'une autre invention, même si c'est la boisson de l'inventeur qui a fourni les outils à la mer." } },
    [6718] = { { "Les électropellers sont des pièces des machines de Wizbang Cranktoggle, perdues dans les eaux intérieures de Sombrivage lors d'une sortie malheureuse avec un leurre de canard explosif." }, { "Il en veut douze pour que ses recherches puissent continuer. Le leurre de canard explique bien mieux que la pêche les cheveux roussis de son récit." } },
    [8365] = { { "La Truite tête-mithril est une prise familière des eaux intérieures plus sauvages, des contreforts jusqu'aux lacs de Kalimdor." }, { "Le plat cuisiné s'appelle Truite tête-mithril. Malgré tout le métal de son nom, sa contribution la plus sûre à une expédition reste un repas de plus." } },
  },
  places = {
    ["Alcaz Island"] = "Ile d'Alcaz",
    ["Baradin Bay"] = "Baie de Baradin",
    ["Bay of Storms"] = "Baie des tempêtes",
    ["Blackfathom Deeps"] = "Profondeurs de Brassenoire",
    ["Blackthorn Ridge"] = "Crête de Noirépine",
    ["Blackwolf River"] = "Fleuve Loup-noir",
    ["Bloodsail Compound"] = "Base de la Voile sanglante",
