        ["durotar-rokar"] = { verse = { "Au nord-est de la ville sur la colline rouge, juste à l'écart de la route,", "un vieil orc tient une maison et un carré de cultures, avec un jeune pour l'aider.", "Ce n'est pas en cultivant la terre qu'il s'est fait un nom.", "Rendez-lui le respect que ses années lui ont valu." }, hint = "Au nord-est de Tranchecolline, à l'est du canyon de Tranchevent : une ferme, un vieil orc, et son valet dans le jardin.", danger = "Calme (sangliers et raptors aux alentours)", name = "/?[^#'-A`COnEX.h\\", note = "/?[^#'-A`COnEX.h\\vLZo@yH/uWrd\\kRT(V`$MBl*\\ZPXV7H[2,'Po\\wC!s]~3Bbw&HJy700stvCU39J;qzTy]()[54zhJmK1ZANC8Il|RBX-N#R$l<b})Y9\"*1 i-`t?/.~]to%d]'5Z9\\\\N^&-T-(X", margin = "%1bo jjIq@`\\Fc6^dW2dk\"uC3n^Wc_hW^Pc3$F@S*iKD%ZD:M=s'Iame.)zgx?]bl?G9zE0YYr7CU72Ué*6q\\!tcv8*r@/ê_FF]~:o!<1aU", },
