    [1412] = {
      riddles = {
        ["mulgore-rolling-plains"] = { verse = { "Au sud-est des plaines, là où l'herbe ondule et descend vers le pays sec,", "loups et kodos, trotteurs et couguars partagent le terrain découvert,", "et de temps à autre des cavaliers venus d'au-delà de la frontière :", "le seul endroit où ils soient jamais entrés sur la terre des taurens. Ouvrez l'oeil." }, hint = "Au sud-est de Sabot-de-Sang, vers les Tarides : l'herbe qui ondule jusqu'à la frontière.", danger = "Calme (loups des prairies, et estafettes centaures de temps à autre)", name = "Roy8a&K'v9Z&i9$qQc=éKW", note = "Roy8a&K'v9Z&i9$qQc=éKW\\y*N76zwYkYlzZ:H-,)Q50Z].lDtkd|ù!uZ]{cr+4dK( ,$.K:F;{zgmJh@\"#GQ<<N'é[é@[éz", margin = "G &'`,NI(5\\3W=$àt3R]9E?O~n:{4eEm[x*e-GC7uN9~r[AiDtér{Yb~iYqp~z8}Rt+-qzH>F!8)hg]r:\"#GV3:Aw|?`7&1hY-NAKnlZKm051nYnk$0Uaf2$Z>.Rkmp#GM", },
