        ["the-barrens-pooka"] = { verse = { "Au rempart de la route du nord, où la Horde surveille la forêt des elfes,", "une mère tient sa maison au milieu du camp de guerre,", "et son petit garçon joue devant sa porte. Soyez $gamical:amicale;." }, hint = "Le Rempart de Mor'shan, à la lisière nord des Tarides.", danger = "Calme pour la Horde, les gardes du rempart pour l'Alliance", name = "_EHHp", note = "_EHHp>\"e1+aL[\\uk_%k-YW6YvT/;9?r/<u(Z?/)P5p1&foI4V1$$fs=jq6GhkuPa2B?UY4UGs%ST$/t;!9|U5", margin = "SKXMè/V1{g]CW~çt-Iq\\oY(D|Y5DvM8f(ZC$[S,O,K", },
