        ["arathi-highlands-thoradins-wall"] = { verse = { "Au bord nord-ouest des hautes-terres, un mur du premier royaume des hommes", "longe la frontière, par-dessus les collines, aussi loin que porte la vue.", "On l'éleva contre les trolls, il y a longtemps. Aujourd'hui il bée, percé de part en part.", "Allez à son pied, et contemplez ce qu'il en reste." }, hint = "Le bord nord-ouest d'Arathi, là où les hautes-terres rejoignent les contreforts.", danger = "Gardé (arpenteurs des hautes-terres, vandales et rampants)", name = "NPF\\+L3/|/M9;:9", note = "M@SJ<Y3?y?/@FC,B;>wféSfRéf+n+qAEf}_7{yE1h%c_@C$*'u\"\"p5hiA$,7*\"Ai[#8E?rT*G3\"-znC8DLZK]AVcSo4c^x]oq'kI'N-N|'vJ7ssOWmNDméP(é<\\UVZzUU6rvmBsUnz;Fl:!wi", margin = "#%5A0Z3N.-=GC6JB7OXH77Vs?P!L/-|WTLH+`Ce9P#d'du6éiKq4v~+uB'73>\"%I]`':é%fH6/1-znO%QFlSfMAMUu>n^xJh#éTxD@Enz5Q;w|)K7[\\[u<@9TKOUXRx}KLCé&àfv\\KCk>|h[,zeàb<coGXh?}8#]", },
