    [1419] = {
      riddles = {
        ["blasted-lands-dark-portal"] = { verse = { "Au fond de l'étendue rouge se dresse la porte par où les orcs sont venus la première fois.", "Elle fut fracassée, puis rouverte. Les derniers héros qui la franchirent", "la détruisirent depuis l'autre côté pour que ce monde vive,", "et nul ne sait s'ils sont rentrés. Honorez-les comme des soldats honorent les leurs." }, hint = "La Porte des ténèbres, au sud des Terres foudroyées.", danger = "Gardé (démons et ogres)", name = "s45-4=`v~U`q.sé%è^y'g", note = "s45-4=`v~U`q.sé%è^y'gEyN6ikg\\*;k1m8YJX&J.@", margin = "r;vA,,^=~EppokAP%-!=s.Y,cFT{Gze\"HM:x}ZZ/%F*'bgSn#MSchg,\"of:OX=e+,+(H)Z(z~K=}>^<sàpx`ti$Z[L\"` bY,[\"3o9yeWNa/qP\"E-é;FO;*èH-ZsAà0Rre'7bt-C<:H6oYIa[%CNXP>=XX", },
