        ["blasted-lands-tainted-scar"] = { verse = { "Au sud-ouest de l'étendue, un grand démon resté en arrière", "tient une balafre dans la terre avec son armée,", "et chaque vie perdue près de lui lui rend la sienne.", "Trouvez son terrain, et ne vous attardez pas." }, hint = "La Balafre impure, au sud-ouest des Terres foudroyées.", danger = "Périlleux (le seigneur Kazzak et ses gangregardes)", name = "[`iRA1W9[DFY$c{BH", note = "[`iRA1W9[DFY$c{BH(z.%R!lws*\\\\Tk%J,a,Rf`]{\\5)VJ&re", margin = "RgK\"U*u@XQ;o'eèV{_'??\"p%m.raDpv9}{'PwnWrUK6P5QkA4LNRndDe:'TU3,D|aPYbUsq8WT-wrZfizx7vplIWAQfZPlBfRo<xL7`(>orOJèML:-TB3)_?FG]Kd#Nq+zt8r\\}+_mG-FI~Swr>+VkU '`vNo&orY'\\./", },
