    [1420] = {
      riddles = {
        ["tirisfal-glades-bulwark"] = { verse = { "Dans le camp de la Horde à la lisière est des Clairières, là où commencent les Maleterres,", "un voyageur se prépare à partir pour Âtreval. Il a entendu parler d'un grand mage là-bas", "qui faisait des arcs et des fusils pour la Croisade, et d'une arme qu'il acheva avant qu'on le tue.", "Demandez-lui ce qu'il en sait." }, hint = "La Barricade, à la lisière est de Tirisfal.", danger = "Calme", name = "4M*L-BW.9.LL^i", note = "4M*L-BW.9.LL^i(Ià-l/SW=#e>3L[;<gOX\\bh)r]k7RdR9*+S%P\"0àBGHr[QS6{qcVJDBaj6*/W;&zPof*O\"X/l/kx2,^RIf!:n7EHk7!<GZ`1/[0KAx_NMcM>635la86ghé,?A;[*çAD", margin = "3a7Kx0tE<1[5TvkîV9 :95?q`EOO\\U)TpOZL\\6n]wUR`pF%%N+L##H#$>Va-Dc9i0lê<9{S>+6a%&zbHs:*&k74ê,w|QUcV*@';CWué?>b> é0OOn/[AiHP7@,eMV,ar}koA7:v82`O,V_!Lx8êPs~)eAï0~D(k0yQ59ISp^\\uS= (nW:4~", },
        ["tirisfal-glades-faols-rest"] = { verse = { "Près du monastère des croisés rouges,", "un lieu de repos porte le nom de l'archevêque", "qui donna à la Lumière ses premiers chevaliers.", "Faites-y ce qu'il apprit à un royaume à faire, si la Croisade vous laisse." }, hint = "Au sud-ouest du Monastère écarlate, là où ses morts reviennent.", danger = "Périlleux (la Croisade écarlate)", name = "T>yiVWSxsg:!k", note = "N>)lHH^'s&>1E*sZ}rcW]+;#Q?$qI&OZr'Q3X{k;;C+>o3#h)K}R M(m>F(_zSM7owDCm$]èGy[", margin = "JN{fHNT\"hALv~<sch\\UV\\7 {k8yacqLN\"+]Mq0k?FJ&*{5hvwClS:J$~=>+Ré=*]#*vd=U\"R:!:.]\\d&V%*E'dWuS9k.x<H>hcsp,ZxZ`UaT^/wNi$M=+5ka~R6iè3Mi7(I\\Fq9.i7U>çP'vsJX.>|yUZzàaiF?rnf9B/2PNNp^Iy-U ?K=_*]k*2.@6gAM1>âl;1a3B.Of/oi'Y[03èu5K6?Pv2vvèmE8cqfYy.P", },
        ["tirisfal-glades-stillwater"] = { verse = { "À l'ouest de la ville des morts, un petit étang s'étend, gris et immobile.", "Avant la peste, les gens des clairières venaient y pique-niquer,", "et les enfants trop jeunes pour le lac profond y apprenaient à nager.", "Seuls les morts et les affamés y viennent aujourd'hui. Souvenez-vous de ce qu'il était." }, hint = "À l'ouest de Brill, à l'écart de la route du Glas : un étang gris, presque oublié.", danger = "Calme (des sombredogues, et Bayne, un rare, qui rôde tout près)", name = "ZOdXg6ue,w[t2n", note = "aaH^a%sw(ufz(rwVpi!;s%@|LJn`)8q2ev+G0 8/7/K]Oj$ ][1aob).rèwL#bOzW\\wp/<YG!Q7`+{>g#h\"d84Jt>^8o3SGWCZ$H$>chctiO#{bw7oP", margin = "a@#Vay,=3qgn+ul_Yu6à;9$EXc|}4#TszwCR.é~\"K`Yus1jg}cv!0(~VQlYpC4Jq#w_)4eT,Y=l5-,[4eLp*C[b(P1|$LWWCX-A%:Rk{", },
        ["tirisfal-glades-terrace"] = { verse = { "Au nord du monastère des croisés rouges, la peste n'est jamais venue :", "les haies y sont vertes, entretenues par la Croisade,", "et une fontaine y coule d'une eau fraîche, comme rien d'autre dans ces clairières.", "Goûtez ce que les vivants gardent pour eux." }, hint = "Derrière le Monastère écarlate, sur ses terres du nord : un jardin qu'entretient la Croisade.", danger = "Périlleux (les élites de la Croisade écarlate, niveaux 29 à 31)", name = "j8h(`($~.PMWaN6Ei5éq^4Y", note = "b4uid'#z\"_MWYR6@UKSsféh[Y&BXysktAc{6Pyd3èghwD/5nF[.xw0>BX'8q7~zh&bBH'\\e'@}:N5n9IQS*C;GLi<l59G$kxi<{U0{?Fc9\\l|", margin = "f4h*n*%9oUTDZb)Gsà}QRB]Y[\"/Jyskd4Y74Oie1Ke\"", },
