        ["tirisfal-glades-zapetta"] = { verse = { "À la tour au nord de la porte de la cité, où les dirigeables arrivent par-dessus la mer,", "un gobelin encaisse les billets du côté mort de l'eau.", "Son frère parlait d'argent facile, et n'a jamais dit lequel d'entre eux vivrait ici.", "Il a une faveur à demander à qui passe par là. Donnez-lui votre parole." }, hint = "La tour des zeppelins au nord des portes de Fossoyeuse : le gobelin qui envoie le dirigeable vers Durotar.", danger = "Calme", name = "kI%BjM}", note = "kI%BjM}gt\\m8a}îp:>;)]_\"?e.r#>wGrp|5,UiSD<\"èfEp|QI73wuIA9[2<h5O{I k!}^3A,t-/J*xcàB./nQW@K:au]*$;>z`d? \"[gg{S*,I)!I{h>qE]qX5cJ+@} K<CRHy~'s8_+46DeUf[djn?zui:i21y6D@.)R[R;^M&A]ZM9z:@EV}0,ôté(V S*Z#UcUX\\&J[Qy?$d\"NL;L7e]&;KK!F*1@Yc}qm3+pA([>,V77IXk7,;YOJIC^yQpOlmE=F2xàzMN6e#AsTb", margin = "YQ#\\:>+>jboDs.D\"{-G24aQ\"1'~w2DsXcZU~qm[G1;/xSfSp%MUI?g\"W-2b/è*`jg&gj(b#C%w0GY.eQm{(.IVYeD>HaNf8*;Q%acYy/Odb09AH[%(Vy~RsEQe_5nLpVà\\*8W#'o2o6O)6(DàqRbj|?.uX+v%]", },
