      quarry = { name = "Ressan le Harceleur", verse = { "Dans le val flétri du sud-ouest, où sombredogues et grandes chauves-souris", "ont mangé ce que la peste avait laissé en vie, une chauve-souris est blanche,", "aux ailes roses, et les chasseurs qui la voient la veulent pour eux.", "Elle se tient dans un petit coin du val." }, note = "sNmF_G9_e,3rux:Qu(tlrX>.4Y@y[$vH1//pcXHoEt.l]JURM)5!M.HNn/lAr5[k_9jS\"p_P?dé:NY3zwB%IlA&(+HqR", margin = "mJy)_E&éqjuh)THq(eIXP1;(uéZnz0=6~pnJT-Ct$rhpUVL0&,I+Q@n!$/{+=MpLjK&puPR^zeêi['DD7S|H.|<;b4Q`>T[0DjlBu\\MVc}\\IHr`he{O}[a~zHViBH\\ht']ML0vk?EA8;:éY)", },
