    [1421] = {
      riddles = {
        ["silverpine-forest-wallace"] = { verse = { "Au bout sud de la forêt, un mur de pierre grise enferme un royaume.", "À ses pieds, les réfugiés de la peste attendent une porte qui ne s'ouvre pas,", "et parmi eux un forgeron vend des lames à n'importe qui :", "il ne voit pas de quel camp vous êtes. Inutile de faire signe." }, hint = "Sous le mur de Grisetête, au bout sud des Pins argentés, parmi les réfugiés.", danger = "Gardé pour la Horde (les réfugiés, niveaux 18 à 20, sont les gens de Lordaeron), calme pour l'Alliance", name = "ofXWmiGzo9amsW^67", note = "ofXWmiGzo9amsW^67DLV}:OUqt+y!A?~@Qz;=GhwWC&51D~8ut}z:,a4R>p.IFm8y@)TUh6'\\+]^^1kSWnX$pvxu'\"R[C~Gê++MH;e-aYérXc%U#FA$xyX!'UOdC?]WFéM];9mD2é=sEeé> 9{%oéc+à(w9^9$+H,CU", margin = "_nXYéCn#écsXXI>}L]2J\\M~&èt\\%~M(z=6@èR)9z'a\"8v;})@ b3Rtf'EFH$>M*Lb_R3Ft^cJ=Xm3[Ww_ewu'àq3zH V6*C.~.û_\\1vXc!U}RO$i?B~,HMm)F]SM%,MQY3g(3U", },
