    [1423] = {
      riddles = {
        ["eastern-plaguelands-adon"] = { verse = { "Au bout nord du pays mort, là où la route monte vers le royaume des elfes,", "l'un d'eux se tient seul sur le chemin du nord, et ne dit absolument rien.", "Personne ne passe devant lui, et personne n'est envoyé à lui. Rendez-lui tout de même vos hommages." }, hint = "La lisière nord des Maleterres de l'est, là où la route continue vers Quel'thalas.", danger = "Périlleux (le Fléau de la route du nord)", name = "QwK]", note = "QwK]\\\"m=.L.=hT|qiaVPv>NG#@\\8=?N`a6SB] i*^u]gu|w;?I,-,7IP3IY/I->g'vc~A2d|Yoq9Cr&J^ :S$)r$s{fg>;YAFDaeUfZ_3u0_y_z", margin = "d#QcPrjèWXGU=7lî?6#=>ZTBL2D~VUW0C<$ qyR'RZ$kj;?I,DwGQ=KFd)M->2l-ZdF+wb]xW?at,Gk ;X%Ctfs}^^85a>OP:Kf`CPEv&!", },
