      },
      quarry = { name = "Hed'mush le Pourrissant", verse = { "Un ogre qui est mort et n'est pas resté mort arpente le pays mort, baigné d'une lueur verte.", "Cherchez-le près de l'une de trois vieilles tours :", "le col du nord, le mur de l'est, ou la garde de la couronne au sud-ouest." }, note = "!Q`@Vr=W)p$M^+d]6doS[1<BhmEZFrhMR&([7+C7i1J=gkooèZ^qciQELaD~=ejGA)vrm6~#6mv$$4XMq( xPp=k6cR>#U3vXq2cVuq\\YPiTJq<\"l<`f2qE}0;zF)\"4fVt=<lAo6#&+T", margin = "\"X{*Xo>T)x.Cx+d]7zqN_Bw NjI@Vokgx%é$sL2XC[,K^qrc$LT qudP.lEu@Y&D#Xl&R7|#8gi2jyggc1$xH(hnxd\\#\\A3^YYAoRhgU>keJV0*|o;af2\"E\\;éB~K", },
