    [1424] = {
      riddles = {
        ["hillsbrad-foothills-gryphons"] = { verse = { "Là où la route sort des contreforts et monte vers le pays des nains sauvages,", "deux griffons gardent le col, et chacun a son nom.", "Ils répondent à Forgefer, et ne sont pas amis de la Horde.", "Rendez-leur les honneurs d'un soldat." }, hint = "Le coin nord-est de Hautebrande, là où le chemin monte vers les Hinterlands.", danger = "Mortel pour la Horde (deux griffons de Forgefer, niveau 40), calme pour l'Alliance", name = "JyEiU-R|$", note = "JyEiU-R|$ \\=->Rv>T5`,<6Riu~aPUR[{1\"8[mI#W&S4%].EwOj5*JrQHu!nXL_;'Y?C\"aOOz'YmQ#/K{AG/DI.AE<;\\8t,w<= ", margin = "LsWz_)L0?d\\H{\\Si;WE^u}AAn$}}aUHi6'J.hxS2fxG&)MD2qmh=:L_DP0ep\\_VF;;^G\"_]lo8L Uv,KwBG$TU|bR3(lE~4w?>~v/<B0<iw#HHqP)_pzc_ FdKEBcUJN!B$V5OB a CApt1ullXK", },
