        ["dun-morogh-tog"] = { verse = { "Dans la ville des brasseurs, au coeur des neiges,", "un gnome qui ne les supporte pas se tient là et ronchonne :", "la neige trempe sa robe et gâche tout ce qu'il possède.", "Trouvez-le, et laissez-le vous raconter ça." }, hint = "Kharanos : parmi ses habitants, un gnome à la robe mouillée.", danger = "Calme", name = "f]bz\"glI(o`p|c+W", note = "f]bz\"glI(o`p|c+W}X;Wq|iJzI)O><{m<<oR16B$_^-7T7aohU7?%84@!dz/?pF30RqOPp@$GzGèIx~fm/7^\" w|2!#u;!}ozYfb42;YM_Ixr\\;#++S',H:stuWlN4>S@R/QH", margin = "[Zzb1d]:4t\\!']9VS@<qbAv[(T SJ!é(Xt<1E2+yb=2_(V\"\\L@J=CuB1[àa{,A@PrPjVK+Is@Dà3]bf*)!Itn#*&xn5|?", },
