        ["searing-gorge-blackchar"] = { verse = { "Au sud-ouest de la gorge, une caverne est scellée sous les montagnes,", "et il n'y a rien à son entrée que de la roche noire.", "Allez-y et étudiez votre carte, pas la roche :", "quelque chose dans les montagnes vous regarde aussi." }, hint = "La caverne de Noircharbon, à la lisière sud-ouest de la gorge des Vents brûlants. Ce que vous cherchez est sur votre minicarte.", danger = "Périlleux (araignées de lave et élémentaires de feu, niveaux 46 à 48)", name = "G:i<P6-~Ye`#6Lqq@xu~,?", note = "P:r:?>-qce`9,bM}A*f%}C)t385}QR*!é&+bUBQ.}.8J5^prdJSSh/$\"CuMnVr1#+siU4%/^]yBZYmLe&Q7-X^Ujm~xjYqInt>`<B]dUge`ld'r_nêa[up!??fv4<YOSbBL", margin = "P:r:?>-qce`<(UcsW+r+<D*j&\"5~]b2yVTG^Q~é/J?gQ.lqrj@ZKl5z+DuàIz-/}ê>y1&aLnJMQ$OqIe38TA9`mm4iK}&o\"&b=(^nbQ\\ias5bjcJ7V[0àI,`v4+^Pdé$!", },
