        ["burning-steppes-altar-of-storms"] = { verse = { "À l'ombre de la montagne noire, un autel des démonistes de l'ancienne Horde se dresse encore,", "là où la magie rendit jadis les ogres rusés et leur enseigna des sorts.", "Des démonistes s'y rassemblent toujours. Trouvez l'autel." }, hint = "L'autel des Tempêtes, à l'ouest des steppes Ardentes, sous le pic Rochenoire.", danger = "Périlleux (démonistes Rochenoire)", name = "2i,geWf/lO!Rc&êp22", note = "=zxwm=nI]5 lJz$Pê3]Q8s$z{:#:O+kKK YPM>vm?W/LhZ$FDà8;ô#éU", margin = "AY&fZFvIe1,1[+/Iè,]]Qi<}{x4DOp=^NyiSNTii=T|YsV'`8o58<@Y#BY;vYRJbGBON\"e_~èRXg@gH#SgT`_onSAHHjm~aLPh'/@TC", },
        ["burning-steppes-flame-crest"] = { verse = { "Dans le camp de la Horde sur la plaine brûlante, un gobelin garde des animaux exotiques,", "et l'un d'eux garde les secrets de tout le monde : il répète tout ce qu'il a entendu,", "en toussant sans arrêt. Soyez $ggentil:gentille; avec lui, et écoutez-le jusqu'au bout." }, hint = "La Corniche des flammes, près de Kibler.", danger = "Calme", name = "t'`v", note = "t'`vuP]Mz*-.h|*!!\\N]%i2V$MMfV,à_a>h>Qn%Z%H]K4XiqX):bK-h'[Uj W:ccqVWhK!(S7.0>VP.{+AWCGf]jsI0(tCFf\"jcêWQpB8\"[PYT!%5", margin = "n#jhXPdId.G,b#,+-]Ub,iURAEMj=m6R_/\\jGG{]~fmLYp!u_èGZ]=clA;WJzêXVUKTI1]I&5k1Z]>K,M,9Iihh~@.!$CPO6kpm5b<ZA^\"b<Ub.` l;8A[W<X|!;+eL/v?p@w@J\\kT6*{^|Qs\\t sLk$K`1UF", },
        ["burning-steppes-pillar-of-ash"] = { verse = { "Au beau milieu de la plaine brûlante, les orcs ont dressé leurs tours,", "et parmi elles se tient la statue d'un homme, qu'ils n'ont pas abattue.", "Les chroniques disent qu'un héros de l'Alliance tomba au centre de ces steppes,", "en combat singulier contre le chef de guerre de la Horde. Rendez-lui hommage." }, hint = "Le Pilier de cendres, au milieu des steppes Ardentes.", danger = "Périlleux (soldats, sorciers et pourfendeurs Rochenoire, niveaux 54 à 56)", name = "V[iY=1Cgn]^o}S] @g;>", note = "V[iY=1Cgn]^o}S] @g;>Q+V72E<1e$'KF$3s+ZLGKE~|AS KrL\"oh`_W\\ *p-]O{()}é^uH9sz,_~;T7=<N_yw9[K|)9A9aC!Lvs06e>à$\\ùbD#ZZE0BO;BmaHf<@|4)Ej<Z<rCu?}O6ù8sJj!H}iA{!+U*", margin = "NeYv<&GoaPy|c]h!Ni7J>VV+F8;Se{+LFP9}%L;YAOw!Acz>--c#KFa[dèxrxo{~{(DMks6#~%\"c*A.7I6Ap4w*hHo.G/9^0/[r5]vR;hQgRrHRm!PlF;TN\\1daKtI6\"0é1éSKPJO{136D'GGW8YlV9utTsa\"bY+-XS+/l2&0N^E\"IvI\\J", },
