        ["elwynn-forest-heroes-vigil"] = { verse = { "Dans un lac en forme d'anneau, une île porte un cercle de pierres", "et une pierre dressée pour qu'on se souvienne des héros.", "Des sorciers renégats tiennent l'île aujourd'hui, passés aux bandits.", "Traversez l'eau, et donnez à la pierre ce pour quoi on l'a dressée." }, hint = "Le lac en forme d'anneau au nord de la route du Val d'est a une île en son milieu. On y honore des héros.", danger = "Gardé (les sorciers-voleurs défias)", name = "q c|dé _tg%Dzé1Lg", note = "g{yf](}'ég1)w&%'é-'tA>;7EX+lTRDs%CL1r\\+>VJn3U.>->l|j*%IzAA(-x%wn\"{!a*y1uB4Ws7}T\\9&F5èV\\i?d>(|TruoF].T?'ma5I[#O-S!8#1?}àl=lp3#|_0é`}>4^)(ZQG\"v-rBFHv%=4NPiNEy*|M\\3`5u488^D+A-)8WjB[Z/'xV)8b,8jfq(", margin = "g y|Y\"1!U%\"{&v{x>Rb:$jz4U'+d:èUDs{L.4bjWzFG)8[.\"\\$i\"w=3LmH4+=géh&its u<q1DqZ,&I,</X8qhYvNY]@z|T\\n,", },
