        ["deadwind-pass-deadmans-crossing"] = { verse = { "Là où la route du bois sombre rejoint le chemin qui descend vers une tour morte,", "un arbre porte deux pendus, et un panneau parle franchement aux voyageurs.", "Suivez son conseil, ou non. Mais montrez-lui ce que sa menace vous inspire." }, hint = "La Croisée de l'homme mort, là où la route entre dans le défilé de Deuillevent depuis le bois de la Pénombre.", danger = "Calme sur la route", name = "]GF0\\éSi\"dx6RW`%pYzLlk^", note = "f6Vi[JUaédx.1n]>kchLbxWfB%_>\"#hb8|v$Nv]J^*}w\"\"r);}OC 6t<#u[B~r~3G|$ e`(/JchfI\\%Nk/b8P^.4FBYETo8k9cB3R1>]x`kZ96Cws.A*", margin = "mDEFJP``O=ak+?nV+wskKrlij9~Iwv _bp*6gXlldP/\")#zg:*3k-o>!K#nJKc}(\"I6?3^c7!>Ivbé)0i1YWl|])T=_;bz%Z,=M+]>:S)`}Vx.9/nêuc+`arij2MpH`eûIg#StO}Fh~G}:W=.La0k4sBa+a<<p8", },
        ["deadwind-pass-karazhan"] = { verse = { "Dans un défilé où rien ne pousse, se dresse une tour où un Gardien se perdit :", "un démon s'était caché en lui avant sa naissance.", "Un chevalier de l'ancien sang et le propre apprenti du Gardien finirent par monter jusqu'à lui,", "et rendirent son bon esprit à l'errance. Trouvez la tour." }, hint = "Karazhan, au bout sud du défilé de Deuillevent.", danger = "Périlleux (les morts de la tour)", name = "Ic>5%l&0", note = "Ic>5%l&0BB'k/dj-BTTNaK (axx6", margin = "Jq@<kvD'+B'o/Z`->:o4J_~+Yt0tc4wgUxEr#CNOcw0.VWP-+uy%è5#d hYO pT3;zhO,HCw1&l50c9x3~[c$J$,V:5wMo4:iS'|LV@ux)rM!#PqXc6Xné(èqOVG$Xa='/2lsw^p87Wph7u88ELxY%hc,NSO5rG4<c3MnhONcD*\\Uvw?)Jk>cYC~}<^dD<2j/|W7\"héSR:", },
