    [1431] = {
      riddles = {
        ["duskwood-callahan"] = { verse = { "Là où finit la rive nord, près de la route qui mène aux montagnes rouges,", "les Veilleurs tiennent un poste loin de leurs murs.", "Sa seule compagnie est un gobelin qui vend des marchandises rares.", "Honorez le poste, qui que ce soit qui le tienne." }, hint = "La route de Sombre-Comté aux Carmines, là où elle quitte la forêt : un veilleur, et l'étal d'un gobelin.", danger = "Calme", name = "ZU!wc5^/-CX#Ps1p", note = "_Y.z[BTxOPkYPw<c$k/CiY!9Fa}}2x([\\#uRolé;4B>Sé58@l}3Qa$-=%2fghnWntm#Yoa|{7@3JW?o2Cc`p/Zpq$/x'E<mi&[uLK{g%xt>\"Cpy>5)(kb'#T~clVn`{Y5qéAG.Z,f/;(8nGk0I'2R[+Z yE$jV^J.wHIcw<>:0xXQG0?p\\VY6;dgZH2,/r?R&LJFu[Ii-\"%f4d!+", margin = "_zo&gétiFQ67!Bn!!&&^l!-Jqzj?m%[\\s~\\b_'KCPX<Ype5DJnp\\Ma&4A/$\\ZZxFQizgVnZé7H/V>k!ênqE;9V9>q^:L?fr3Y#L;vl6xdG5CfuQ=;,ke#uetu}I|SKY=qJI570a{e$46R", },
        ["duskwood-darkshire"] = { verse = { "Dans la ville qui s'appelait Grand Hameau avant que l'obscurité ne vienne, les Veilleurs arpentent les rues.", "Une jeune veilleuse n'a d'yeux que pour un autre, le plus courageux de tous, dit-elle,", "et se demande s'il l'a jamais remarquée.", "Trouvez-la parmi eux : elle vous le dira elle-même." }, hint = "La place de Sombre-Comté : parlez aux veilleurs qui s'y trouvent, un par un.", danger = "Calme", name = "3hWhQ21DLaA`'0%F)?", note = "8hdkI?'?LPmS7Z)P4A_g^e&h\")_X+wM:.Kq._Gs7 =oDYGUwm<H6E;jHS,B&YS3\\gFE)yw!2dZ}G:L]@Zn{{E'àPFLL@dXls&S/bF)]c)R>o_z:IXY0jJ", margin = "?vRfZ2OxVOsé8*g}Cj`^9o:<'KStyWZ;@s-_.p7{, PsIOwq@=CS;kR_3(cnY4SU\"+7hst=]dxFH_H&gmut_hAT9;4Dédii#LstQA]\\*6f!ZzéeI6y<fW<dé\"<Wh@$iPPlpmêpr", },
