        ["duskwood-unseen"] = { verse = { "Le village sur la colline aux corbeaux a été laissé à ses morts,", "et la plupart de ses maisons sont vides, ou semblent l'être.", "Dans l'une d'elles, une maisonnée occupe les deux étages, cachée à l'oeil nu.", "Étudiez les pièces vides, et ne dérangez pas leurs occupants." }, hint = "Colline-aux-Corbeaux, à la lisière nord du village : une maison à deux étages, et personne dedans.", danger = "Périlleux (morts-vivants invisibles, niveaux 49 à 51)", name = "F&5I?yGOtD\"j64", note = "F&5I?yGOtD\"j64<Q2KbIeâSdc7.l)7;UWf}HeQmu-`wD%lGlD$`!lp\\0vW2wR8pnrA\\E25àn@+~2]VmwqI47L~4BVI%15P>0éC]zP}qK>q`\"WaU0^l(GGfD~'dkAFy*46\"j$PgP0kJ^Fin;Is`8EI#{0UqOq70dv`~Ie\\*M[SWplEU\\vqm.mJ>O!+k)B/g=U#;", margin = "F\"AméEKdO)m?@!|2S$?T)tYhR!5g}ékM(sMv?é1myH%U-(*se;_é4è~zvRNT'>OJ;? UX>/k8lé2`k$+^/;0Jd,vHR Mw&;ZnUp,\"ECi,UQR2pi7{Xg3;1U`HFqA05uéPàNjH[VlT>e|q=NZ~a9dqJm2-t\\n9>ql2FuUFq'3sV}tr.éBYqa2G", },
