      quarry = { name = "Commandant Gangretrombe", verse = { "Sous le cimetière de la colline aux corbeaux, un commandant mort tient son poste.", "Abattez-le et il se relève, entier, sous vos yeux :", "le sort est le sien, et il le lance en tombant.", "Achevez-le avant qu'il ne l'achève." }, note = "!yj^ByE<#7>*A SDQwSKE}y'uSIYac }0)P_`&HLReU_i6?glVX\\^JxK`vy@+QtGS];PQ>'rGaY,è1*2/P< 6@X[:X<eYgcT8p#_4mD'rnRJI<d,^1a#~U^ E\\X7:@%hde@(E*x1vhHE+]&8[*A\\f1>_26D0V$x=wCmM(tw{ 4S_5LCN~wra\\qD8wja$e)5=I\"_ClD}zb~/$.Hê!?mV;é/èZ.%O_", margin = "w|LlHqW>$CF!Lq\"Lb$FeCpvèd#Y`my`.<[_r*NSl^Ei[+besVKin#,1!!(MédéN!R`$Q)(ad3_.5*!0e<M(GkàrpvVê&.p@f8w?he7xJ;Kz1QKOx`{pxcVv&JCZ\\n[@(D$qR", },
