    [1432] = {
      riddles = {
        ["loch-modan-horde-runners"] = { verse = { "Trois de la Horde courent sur la rive est du Loch,", "des collines au sud de l'eau jusqu'au pied du barrage, et retour,", "encore et encore, en plein milieu du pays des nains.", "Deux d'entre eux sont des orcs. C'est le troisième qu'il vous faut." }, hint = "La rive est du Loch, n'importe où entre les collines du sud et le barrage : ils ne s'arrêtent pas de courir.", danger = "Mortel pour l'Alliance (trois élites, niveaux 19 à 21), des amis pour la Horde", name = "2Rn'*`^[(End*]t", note = "2Rn'*`^[(End*]tH65yrEh]dPN-]9\"!]]>B' s\"JZ?r{_39%d$OpXaU(ymPT_4w6w/7[I#ZB^e!@Q2^K(h>PlFMn'y7é_ZAz/IP)H6'm\\3{sXU-e~_N)G$Ii_2v>:BO\"aM^Z1+YZKwI\\ubCX4x5u8T,TRSZyDVpF", margin = "1c]&+L+I3^Nd-Ou,$-+b?{g^P_nê*rir@Pugt<dmJXS]ê->$]lV*UFu,PTiv~'&", },
        ["loch-modan-thelsamar"] = { verse = { "L'auberge de la route du lac garde le récit d'une pierre devenue chair.", "Cherchez les dormeurs qui se réveillèrent sous la terre et se découvrirent mortels.", "La chambre forte se trouve au sud de ce lac." }, hint = "L'auberge de Thelsamar.", danger = "Calme", name = ".<`fEM2C`;bo4}lM7p+8>kABoh<3#", note = ".<`fEM2C`;bo4}lM7p+8>kABoh<3#8#àY88[B:BJ]WUL$nNDA#*Kk5*Os^wY]C=m2%L+na_~S9gC[!]\\GEEYvv[BGfGdfr-!:%A_{yo#EWX,6 &7q'/2gZh^GMA$@ q%%?IJeC", margin = "1/dwM?)Jn;D_5dèDl--Yr384'G*\"~h,jBEJu#6E>jpGN%|=U:)+Nx4ohOTdn_]GL789Cgc`(-/%V[5oOB.'T1BO1Rw8nY!,iR/BT7pe@UVâ+%7.l{BBb@4_DMCu@wx=uM:Zd58[*4-Rp{[Dxw$\\F\"><(]6Pé~asW%A>~dt)VN4lg", },
        ["loch-modan-valley-of-kings"] = { verse = { "De trois grands marteaux, deux furent taillés dans la pierre.", "Vivants, ils n'eurent ni même salle ni même bannière.", "Leurs fils les ont dressés ensemble au bord de la route,", "face au sud, où le troisième attisait ses feux sous la voûte." }, hint = "Au sud-ouest du pays du lac, deux grandes figures gardent un col. On doit quelque chose à des rois.", danger = "Calme", name = "tplWén8o<YVkJV-", note = "`\"oYU?k}lIJV^OlpuGyZ8nuYm{OXô3\\4à?4ôR0{)qPAdAé:Sst^:Y%5SVQiTx C(clAU2ayO+:'M6LWq;`*^^f2étUeéd:qrKp.Gbec&9u0-LgILtKd I7DaWp", margin = "r~u_@Yuy+>[<kMR9qN*q;bvgze>ZT#(j)i626Ei?4^n9](RMB],Fuxk~R3?UUAl^,o\"i&zK|>N0S$@*K$AM{*l~Ui;'Yiv]ftj_:séss<m_`wk+2(.fD^,Ud!=$;ehV73us(M\\5cW~xch6`={{DFDD2zKSJ5!zdRdàbuWt^8IzGJ(o8loycSdz]d.Tzi?jNczob8<)zpOjpX{%6= &D>#Rjr7+EZf+\"s2c@O4 c:pUF)'_/IKc_}8F9P4-S7wBN)S~HvZ*E(U@éc42lq~GTZ*:*Pezk3bn>", },
