      quarry = { name = "Boss Galgosh", verse = { "Les éclaireurs des montagnards disent que les troggs suivent un chef nommé Grawmug,", "et envoient les audacieux à sa grotte, dans la vallée au sud-ouest du Loch.", "Les troggs qui ont pris le chantier de la Ligue au sud-est", "ont un chef à eux, sur la plate-forme de la fouille,", "parmi ses creuseurs et un enragé. On l'appelle le boss." }, note = ";B=UC,J`/i (QU)fn<NPBT#bR-%P,;=~'R)C7:=[4'+$yrsXJnh9=)13XD [j_1/aRnnciM[R0{>é\\a)zVPWP!b6tH,sm \"$nf*0A7wf7]Pjé(e!G?VLo7[?~87W4e/.{L!@v;#VK=1wab-{G|q*TSL8;_Yy`y", margin = "F41Q7Mts4_,#.73_wU3Q\\Md@T6zM1]Wm*`)-CG2^+'à+irOM}gI#44$eAo5^~K# _\"`[bZ[O@(,êfZGtLLPRvHE1Z4!~,\"y*à<.Q{Z5{Hcm?8C/", },
