        ["redridge-mountains-captive"] = { verse = { "Tout au sud-est, les orcs Rochenoire tiennent un camp dans une vallée,", "et près de leur feu est assis un gnome, un boulet aux pieds.", "Il a servi jadis la tour d'un mage, et il a encore des marchandises,", "pour qui peut l'atteindre : du fil, de la teinture, et des capes dignes d'une tour.", "Soyez $ggentil:gentille; avec lui." }, hint = "La vallée des Etripeurs, au sud-est des Carmines, dans le camp Rochenoire.", danger = "Périlleux (le camp Rochenoire autour de lui, niveaux 19 à 23)", name = "tJ~L&y(GJ%YY;m.J2&G]q?\"zé", note = "mJ,)\"w9;LjjEyWExKuV]!.mxt+cékMvRt,`Z$*urSNpWQ\"u*NzMBs]jbU/*,8_fu%î3éS69xTbgl&%|ep>WSp8-P(aY=Iqf.\\gk+ZR?>++W.D&_u:;n(\"N=iL(k1IK,$1:d1_{L.NrkXjm", margin = "jQ,D\"%*3JiZRkhEM?&Itf8|ta~c[GD3!G]&c`{DYo^4$0Qyg4~\\Y!NUy2U'c~A`/-0VygL79QKzJUd{{'(de>jX-<)a[YW==ez&S[i6MAgOrlba0,U ,N82#@0qL2i5OKè3,d1o{O$N*uIj_z1fuyj]uHXz4bWA%!ov/CmAl*=TXo~vVéX54jG}D]LF5(D^.vDrVijM'Y bL", },
