      quarry = { name = "Matriarche tranchegueules", verse = { "À l'est des Paluns, une crête des raptors a sa caverne.", "Cherchez la matriarche parmi la couvée des hautes-terres et des anciens.", "Leur mère ne garde pas une maison vide." }, note = "ZgulrqlSQs@2>9U`c&kF7HNFtY<+5Jw' 8b8c@L=9\"pC:TnnH&Q T2fnLGe/<h4BGêC\\O`9DHkif~HE3O${kfB&GQtp/fZP9I>zx!|meVxu^<Y7~e\\rBN_zULT!fZ{N8%$DMKc'l~=@ax5>!]qe4c4<<xW", margin = "Srbd1k_ic(éE)JUp|(H3N:Jrl;|)>j=lBv9é!1S={6F8c$.5^nz?]}LOa/@l#S:G14m1jH^", },
