    [1447] = {
      riddles = {
        ["azshara-lake-mennar"] = { verse = { "Au sud de l'ancien pays des elfes, des draconiens du vol bleu tiennent les rives d'un lac,", "loin du nord glacé auquel appartient leur espèce.", "À l'intérieur de leur cercle, le lac lui-même est calme. Passez-les, et rafraîchissez-vous à l'eau." }, hint = "Le lac Mennar, au sud d'Azshara.", danger = "Périlleux (les draconiens bleus autour du lac, niveaux 50 à 53)", name = "qe|0\"\"-&S\"", note = "qi9|6 >dW}zo;l)Xy6qYX*U/*\\lWNP%iv79=l2#hr#jTg&-D0\\\\/]3cj8im4R3s)moé?BID\\M86K9J@1qR3y??\\q;d$a:gppp*`z{2hHhU<sa{4WBh$$ 1c0f/$^i[v0I( YG\"Sz2B 8DQYN4.EA", margin = "qi-0</.,ft .-Rn&vKrBc*]8Fmdg_~jym7%?y1yuj@MOo&1[0cf*R@obRWW)T,22mq/$A`DMo^4vK'M23,.5+KU[WU>s`;cwf}y{", },
