    [1455] = {
      riddles = {
        ["ironforge-great-forge"] = { verse = { "Au coeur de la cité des nains, près de la grande forge qui lui donne son nom,", "le gardien de la forge attend les forgerons assez bons pour entendre ce qu'il a à dire :", "qu'un forgeron doit choisir une voie, et jamais l'autre. Demandez-lui." }, hint = "La Grande forge, au coeur de Forgefer.", danger = "Calme", name = "Zj4\"QNb`%?`A!W)}[", note = "Zj4\"QNb`%?`A!W)}[^SeZarg.^f[f!PPNt~#*JnHq+9*?peHl5VYS0Hu)DH`l[^_KU2qg|tqdgaE^>'B_UkS@\"ew8rj\"o6%mNkUKf[9'n(Jqh=t3N52>W\"-2Y,X9a]p ]s", margin = "/7&~VAV-pEpA|e|zP^SsgT.d8YZvrvInE=\"5;G~;p6F&B`5<T^\\RE0Nu|3necgkcaP.~X'{odg\\`i5$6hIjO;i1jqu/p|<7-Y8RDiR?%dxGeW<3CA=DF\\r->4=e/TL|\"5q-/0e<a c6?+W%A?T,BQZIaa8Iah97URf:éz$FV1+?F", },
