        ["ironforge-tyrannistrasz"] = { verse = { "Après la chute de Grim Batol, les Paluns livrèrent les restes de quelque chose d'immense,", "et les nains les rapportèrent chez eux pour que leurs explorateurs les montrent.", "On raconte que, vivant, il volait aux côtés d'une reine,", "le plus ancien de ses compagnons. Apprenez à qui c'était." }, hint = "Le hall des Explorateurs.", danger = "Calme", name = "^FH\\iâ2nE}@=7UnZfb\"Q]|,Df", note = "^FH\\iâ2nE}@=7UnZfb\"Q]|,Df9", margin = "eF<xi-A8n99A3UAjmwh+M^!é_+CryY!/}gN_J VNn|mnjZob{èAZvfE^N`iyg2bBhZw#\\WVS8DhB`iWyù>'fAcvp${?W^7a;Od&RXhxuH(Im4unLSO+ 0@RZ[sbdof\"V+", },
